// ─── WEEKLY ROUTINE ("Time Shields") ─────────────────────────────────────────
// A routine rule is a recurring commitment: {id,title,kind,days,startTime,
// duration,subject}. `days` is Monday-first (0=Mon..6=Sun), matching
// WeeklyPlanner's own weekDays convention below. Rules are never copied into
// the one-off `events` array — they're expanded into virtual occurrences on
// demand for whatever date range is being rendered or scheduled, so editing
// or deleting one rule instantly and correctly applies to every week without
// any bulk-update pass.
const getWeeklyRoutine=()=>lsGet("weeklyRoutine",[]);
const saveWeeklyRoutine=(r)=>lsSet("weeklyRoutine",r);
// 2026-08-20: detects routines that are almost certainly leftover
// fragments of ONE activity from before the groupId-preservation fix
// (see saveRoutineEditFromModal's own comment) shipped -- same
// title+kind+subject+time, but sitting under different groupIds so they
// show as separate sidebar rows ("5 Morning Routine" instead of one).
// The fix stops NEW fragmentation; this is the one-time repair for
// routines that were already split apart before it landed. Consolidates
// each cluster into a single object with a combined `days` array (the
// exact shape a fresh multi-day create/edit already produces), rather
// than just relabeling groupId -- that would leave them as "multiple
// placements," a real, distinct feature for genuinely different day
// patterns, which isn't what an accidental fragment split is.
// Deliberately excludes "class" (legitimately distinct per-period
// meetings) and "habit" (real per-day completion history may already
// reference a specific fragment's id -- safer left untouched than risk
// orphaning that).
function findFragmentedRoutineGroups(routines){
  const sig=(r)=>[(r.title||"").trim().toLowerCase(),r.kind,r.subject||"",r.startTime||"",r.duration||0].join("|");
  const bySig=new Map();
  routines.forEach(r=>{
    if(r.kind==="class"||r.kind==="habit")return;
    if(!r.days||r.days.length===0)return;
    const key=sig(r);
    if(!bySig.has(key))bySig.set(key,[]);
    bySig.get(key).push(r);
  });
  const groups=[];
  bySig.forEach(list=>{
    if(list.length<2)return;
    const groupIds=new Set(list.map(r=>r.groupId||r.id));
    if(groupIds.size<2)return; // already one real group -- a legitimate multi-placement case
    // Only safe to merge if no two fragments in the cluster claim the same
    // day -- overlapping days would mean genuinely conflicting data, not a
    // clean split, and this should never guess which one wins.
    const allDays=list.flatMap(r=>r.days);
    if(new Set(allDays).size!==allDays.length)return;
    groups.push(list);
  });
  return groups;
}
function mergeFragmentedRoutineGroup(list){
  // Oldest id wins and survives -- ids in this codebase are Date.now()-
  // based strings, so lexicographically smallest is also chronologically
  // first, i.e. the original object, the one any real history is more
  // likely to already reference.
  const primary=list.reduce((a,b)=>a.id<b.id?a:b);
  const days=[...new Set(list.flatMap(r=>r.days))];
  return {...primary,groupId:primary.groupId||primary.id,days};
}
// Returns {routines, mergedCount} -- mergedCount is how many separate
// clusters got collapsed into one (not how many individual rows were
// removed), matching what a confirmation/toast should actually say.
function mergeDuplicateRoutines(routines){
  const groups=findFragmentedRoutineGroups(routines);
  if(groups.length===0)return {routines,mergedCount:0};
  const idsToRemove=new Set();
  const merged=groups.map(list=>{
    list.forEach(r=>idsToRemove.add(r.id));
    return mergeFragmentedRoutineGroup(list);
  });
  return {routines:routines.filter(r=>!idsToRemove.has(r.id)).concat(merged),mergedCount:groups.length};
}
// One-time backfill for classes added via ClassSetupWizard before its two
// commit paths (commitReviewedClass/commitHsSchedule) started tagging the
// recurring class meeting-time routine item with the class's own subject
// -- without it, colorOf(routine.subject) always fell through to plain
// gray (an empty subject reads the same as no subject at all), no matter
// what real color the class itself was assigned. Purely additive: only
// ever fills a currently-empty subject by matching the routine's own
// title against an existing subject's label, never overwrites anything,
// and only ever runs once.
function backfillClassRoutineSubjects(){
  if(lsGet("classRoutineSubjectsBackfilled",false))return;
  const subjects=getSubjects();
  const routines=getWeeklyRoutine();
  let changed=false;
  const next=routines.map(r=>{
    if(r.kind!=="class"||r.subject)return r;
    const match=subjects.find(s=>s.label===r.title);
    if(!match)return r;
    changed=true;
    return {...r,subject:match.label};
  });
  if(changed)saveWeeklyRoutine(next);
  lsSet("classRoutineSubjectsBackfilled",true);
}
// Same one-time, purely-additive idiom as backfillClassRoutineSubjects
// above, for the newer courseId field: fills courseId on any routine or
// event that already carries a real course's subject label but predates
// courseId ever being stamped at creation time. Never overwrites an
// existing courseId (including one that's explicitly null from a
// free-typed/no-course label), only fills a genuinely missing field, and
// only ever runs once.
function backfillCourseIds(){
  if(lsGet("courseIdsBackfilled",false))return;
  const subjects=getSubjects();
  const labelToId=(label)=>{const s=subjects.find(x=>x.label===label);return s?s.id:null;};
  const routines=getWeeklyRoutine();
  let routinesChanged=false;
  const nextRoutines=routines.map(r=>{
    if(!r.subject||r.courseId)return r;
    const id=labelToId(r.subject);
    if(!id)return r;
    routinesChanged=true;
    return {...r,courseId:id};
  });
  if(routinesChanged)saveWeeklyRoutine(nextRoutines);
  const events=lsGet("events",[]);
  let eventsChanged=false;
  const nextEvents=events.map(e=>{
    if(!e.subject||e.courseId)return e;
    const id=labelToId(e.subject);
    if(!id)return e;
    eventsChanged=true;
    return {...e,courseId:id};
  });
  if(eventsChanged)lsSet("events",nextEvents);
  lsSet("courseIdsBackfilled",true);
}
// Deletes a course and everything linked to it -- its recurring class-time
// routine rows, and every event carrying this courseId (or, for data that
// predates the courseId migration, matching by label instead, same
// id-preferred/label-fallback convention as everywhere else in this
// migration). Pure data operation, no React/UI here: finds, removes,
// persists, and returns exactly what was removed so a caller can offer a
// real Undo -- the same batch-snapshot idea CalendarTab's own
// deleteEventWithUndo already uses for a single event, generalized to many.
// Returns null if courseId doesn't resolve to a real subject (nothing to do).
function deleteCourseWithCascade(courseId){
  const subjects=getSubjects();
  const subject=subjects.find(s=>s.id===courseId);
  if(!subject)return null;
  const matches=(item)=>item.courseId===courseId||item.subject===subject.label;
  const routines=getWeeklyRoutine();
  const removedRoutines=routines.filter(matches);
  const keptRoutines=routines.filter(r=>!matches(r));
  const events=lsGet("events",[]);
  const removedEvents=events.filter(matches);
  const keptEvents=events.filter(e=>!matches(e));
  saveSubjects(subjects.filter(s=>s.id!==courseId));
  saveWeeklyRoutine(keptRoutines);
  lsSet("events",keptEvents);
  return {subject,routines:removedRoutines,events:removedEvents};
}
// Restores exactly what deleteCourseWithCascade removed, from its returned
// snapshot -- re-inserts the subject, its routines, and its events in the
// same shape they were in right before deletion.
function undoCourseDelete(snapshot){
  if(!snapshot)return;
  saveSubjects([...getSubjects(),snapshot.subject]);
  saveWeeklyRoutine([...getWeeklyRoutine(),...snapshot.routines]);
  lsSet("events",[...lsGet("events",[]),...snapshot.events]);
}
// One-off exceptions to an otherwise-recurring routine rule ("skip today's
// class") — keyed by date so a lookup during expansion is O(1), value is
// the list of routine ids not to expand for that one date. The rule itself
// is untouched, so every other week is unaffected. Written by "Studlin
// Reschedule"'s skip_class intent (see computePausePlan/confirmPausePlan).
const getRoutineSkips=()=>lsGet("routineSkips",{});
// Phase 7e: "just this occurrence" edits to an otherwise-recurring routine
// (drag one Tuesday's Geology block to a new time without touching every
// other Tuesday). Keyed the same way getRoutineSkips is -- {routineId:
// {dateKey:{startTime,duration}}} -- consulted by expandRoutineOccurrences
// below when materializing that one date. The rule itself is untouched,
// so every other occurrence keeps the rule's own startTime/duration.
// Deliberately scoped to a same-day retime/resize, not a cross-day move --
// an occurrence's very existence on a given date comes from the rule's
// `days` pattern, so relocating a single occurrence to a genuinely
// different date would need a second, separate "one-off extra occurrence"
// mechanism this doesn't attempt (the UI only offers "just this one" when
// the drop lands on the same date it started on -- see CalendarTab's
// onDropRoutineOccurrence).
const getRoutineOverrides=()=>lsGet("routineOverrides",{});
const saveRoutineOverrides=(o)=>lsSet("routineOverrides",o);
// The current school term's date range, {start,end} (both "YYYY-MM-DD")
// or null if never set — opt-in, so a student who hasn't configured this
// sees no change from today's always-on behavior. Governs only
// kind:"class" routines (see expandRoutineOccurrences below); busy/habit
// routines are untouched since a job, sports practice, or personal habit
// isn't necessarily tied to the school calendar the way a class is.
const getSchoolTerm=()=>lsGet("schoolTerm",null);
const saveSchoolTerm=(t)=>lsSet("schoolTerm",t);
// Term rollover (Phase 8 follow-up, 2026-07-29): has today passed the end
// of the currently configured term? Pure so it's testable without a real
// clock -- callers pass today's own dayKey(). No term configured (never
// set, or explicitly cleared) means nothing to roll over, same "opt-in"
// spirit as getSchoolTerm itself.
const isTermRolloverDue=(term,todayKey)=>!!(term&&term.end&&todayKey>term.end);
// Dismissing the rollover prompt is remembered per term-end date, not
// permanently -- so it stays quiet for the rest of THIS ended term, but
// automatically starts prompting again the next time a newer term also
// ends, rather than a one-time global dismiss that goes stale forever.
const getTermRolloverDismissedFor=()=>lsGet("termRolloverDismissedFor",null);
const dismissTermRollover=(termEnd)=>lsSet("termRolloverDismissedFor",termEnd);
// Calendar zoom (pixels per hour) -- Phase 10b, user-driven, not auto-fit
// (auto-fit was tried before and deliberately removed, see
// computeDayViewScale's own retirement comment, for shrinking blocks down
// to illegibility on a packed day). Shared between WeeklyPlanner's own
// drag handle and DayPlanner, which just reads whatever was last set so
// switching Week/Day view keeps a consistent feel without a second handle.
const CAL_ZOOM_MIN=28, CAL_ZOOM_MAX=90, CAL_ZOOM_DEFAULT=48;
const clampCalZoom=(px)=>Math.max(CAL_ZOOM_MIN,Math.min(CAL_ZOOM_MAX,px));
const getCalZoom=()=>clampCalZoom(lsGet("calZoomPxPerHr",CAL_ZOOM_DEFAULT));
const saveCalZoom=(px)=>lsSet("calZoomPxPerHr",clampCalZoom(px));
// A high-schooler's daily school-day bounds, {start,end} (both "HH:MM") or
// null if never set. Distinct from getSchoolTerm above (that's the date
// RANGE the term runs; this is the daily TIME window school occupies) --
// set once during ClassSetupWizard's HS whole-schedule import (Phase 9),
// used there to derive free-period gaps between extracted classes via
// subtractIntervals. Not read by the scheduling engine itself.
const getHsSchoolHours=()=>lsGet("hsSchoolHours",null);
const saveHsSchoolHours=(t)=>lsSet("hsSchoolHours",t);
// Phase 8: black-out date ranges the term pauses (spring break, etc.) --
// [{start,end,label}], collected during onboarding.
const getHolidays=()=>lsGet("holidays",[]);
const saveHolidays=(h)=>lsSet("holidays",h);
// Bug fix: onboarding's own copy promises "Studlin won't plan study
// sessions during these," but nothing ever checked -- consulted by the
// core auto-placement day-loops (findOpenSlotFor, findTier0Slot,
// dayHasRoomFor) so a holiday date is treated the same as a fully-booked
// day: skipped over, never a landing spot for a new study session. Does
// NOT touch fixed/manually-placed events, routine generation, or display
// (a holiday still shows normally on the calendar) -- purely a "don't
// auto-schedule here" signal, same scope as the copy promises.
function isHoliday(dateKey){
  const list=getHolidays();
  if(!list||list.length===0)return false;
  return list.some(h=>h.start&&h.end&&dateKey>=h.start&&dateKey<=h.end);
}
// Phase 8: a student's actual wake/sleep hours, genuinely distinct from
// workStartTime/workEndTime (schedulePrefs) which is a STUDY-hours
// preference, not "when am I awake at all" -- today those get conflated
// (a HS student's workStart defaults to right after school lets out, an
// implicit stand-in for "awake"). {wakeTime,sleepTime}|null.
const getWakeSleep=()=>lsGet("wakeSleep",null);
const saveWakeSleep=(w)=>lsSet("wakeSleep",w);
// A list of {id,url,label,sourceType,lastSyncedAt} for calendars/work
// schedules the student has imported via /api/cal-proxy (.ics feeds).
const getImportedCalendars=()=>lsGet("importedCalendars",[]);
// Also pushed server-side (fire-and-forget) so the daily academic-calendar
// cron (api/me.js's handleAcademicCalendarCron) has something to check even
// when the student never opens the app that day -- this list otherwise
// lives only in localStorage, invisible to any background job. A failure
// here just means that day's cron pass won't see a just-added/removed link
// yet; it never blocks the local save, which is the real source of truth
// for what the app itself does with these subscriptions.
const saveImportedCalendars=(list)=>{
  lsSet("importedCalendars",list);
  authFetch("/api/me",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"sync-imported-calendars",importedCalendars:list})}).catch(()=>{});
};
const detectCalendarSourceType=(url)=>{
  try{
    const h=new URL(url).hostname;
    if(h.endsWith("icloud.com"))return "iCloud";
    if(h==="calendar.google.com"||h.endsWith(".calendar.google.com"))return "Google Calendar";
    if(h.startsWith("outlook."))return "Outlook";
    if(h==="schoology.com"||h.endsWith(".schoology.com"))return "Schoology";
    if(h==="instructure.com"||h.endsWith(".instructure.com"))return "Canvas";
    if(h==="blackboard.com"||h.endsWith(".blackboard.com"))return "Blackboard";
    // Moodle is self-hosted per school (Lehigh brands theirs "Course Site"
    // at coursesite.lehigh.edu, other schools use their own domain/name
    // entirely), so there's no single shared hostname the way Canvas has
    // instructure.com. The export URL's own path is standard across every
    // Moodle install regardless of domain or school branding though (see
    // PLATFORM_HELP.moodle) -- detecting on that instead of a hostname is
    // what actually generalizes beyond just Lehigh.
    if(url.includes("/calendar/export_execute.php"))return "Moodle";
    return "Work schedule";
  }catch(e){return "Calendar";}
};
// Schoology/Canvas/Blackboard is the one case where "what kind of import is
// this" isn't just a display label -- it's also what tells
// fetchCalendarPreview below to run the AI classification pass (see
// classifyImportedCalendarEvents) instead of leaving every imported item as
// a generic "busy block."
const isAcademicCalendarSource=(sourceType)=>sourceType==="Schoology"||sourceType==="Canvas"||sourceType==="Blackboard"||sourceType==="Moodle";
// Pure -- builds the review-queue entry the silent, once-a-day auto-resync
// (see resyncCalendar) pushes into openImportCalQueue instead of merging
// newly-classified academic items straight onto the calendar with zero
// review, the way the first-connect (fetchCalendarPreview/
// connectCanvasToken) and manual "Sync now" flows already do via
// importCalReview. Mirrors those two flows' own classified-event shape
// (kind/subjectGuess/examWeight/include) so importCalReview's existing
// render logic needs no changes to show either one. Dedups the queue by
// subId (replacing, not stacking) so a student who ignores this for a few
// days doesn't build up several stale entries for the same source -- each
// day's version is already a full re-fetch, a strict superset of what an
// earlier unreviewed one held.
function buildDeferredCalendarReviewQueue(existingQueue,sub,newEvents,classifications){
  const reviewEvents=(newEvents||[]).map(e=>{
    const c=e.uid&&classifications[e.uid];
    return {...e,kind:c?c.kind:"assignment",subjectGuess:c?c.subject:(sub.viaToken?e.subject:"Other"),examWeight:c&&c.examWeight,include:true};
  });
  const filtered=(existingQueue||[]).filter(q=>!(q&&typeof q==="object"&&q.reviewPayload&&q.reviewPayload.subId===sub.id));
  const entry={reviewPayload:{subId:sub.id,url:sub.url||null,label:sub.label,sourceType:sub.sourceType,events:reviewEvents,skippedAllDay:0,classified:true,viaToken:!!sub.viaToken}};
  return {queue:[...filtered,entry],reviewEvents};
}
// Step-by-step, platform-specific instructions shown inside the connect
