// ─── XP · LEVEL · STREAK · PLAN (all derived from real activity) ───────────────
const DOW_FULL=["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];
const MON_SHORT=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
function todayLabel(){const d=new Date();return DOW_FULL[d.getDay()]+" · "+MON_SHORT[d.getMonth()]+" "+d.getDate();}
function weekNo(){const d=new Date();const start=new Date(d.getFullYear(),0,1);return Math.ceil((((d-start)/86400000)+start.getDay()+1)/7);}

// Deterministic, non-AI fallback for syllabus deadline extraction — mirrors
// fallbackSchedule's role for AI Schedule Mode: if the AI call throws or
// returns nothing usable, this guarantees the feature still returns SOMETHING
// rather than dead-ending. Naive regex date-scan, so every match is tagged
// confidence:"low" — the review modal flags these for the student to check.
function regexScanDeadlines(text){
  const lines=(text||"").split("\n");
  const results=[];
  const monthPattern=new RegExp("("+MON_SHORT.join("|")+")[a-z]*\\.?\\s+(\\d{1,2})(?:st|nd|rd|th)?(?:,?\\s*(\\d{4}))?","gi");
  const numericPattern=/\b(\d{1,2})\/(\d{1,2})(?:\/(\d{2,4}))?\b/g;
  const now=new Date();
  const titleFrom=(line)=>{const t=line.replace(/^[\s\-*•\d.)]+/,"").trim().slice(0,60);return t||"Deadline";};
  const kindFrom=(line)=>/exam|midterm|final|quiz|test/i.test(line)?"exam":"deadline";
  const rollYear=(month,day,year)=>{
    if(year)return year.length===2?"20"+year:year;
    const candidate=new Date(now.getFullYear(),month,day);
    return String(candidate<now?now.getFullYear()+1:now.getFullYear());
  };
  lines.forEach(line=>{
    if(results.length>=40)return;
    let m;
    monthPattern.lastIndex=0;
    if((m=monthPattern.exec(line))){
      const monthIdx=MON_SHORT.findIndex(mo=>mo.toLowerCase()===m[1].toLowerCase());
      const day=parseInt(m[2],10);
      const year=rollYear(monthIdx,day,m[3]);
      results.push({title:titleFrom(line),date:year+"-"+String(monthIdx+1).padStart(2,"0")+"-"+String(day).padStart(2,"0"),kind:kindFrom(line),confidence:"low"});
      return;
    }
    numericPattern.lastIndex=0;
    if((m=numericPattern.exec(line))){
      const month=parseInt(m[1],10)-1,day=parseInt(m[2],10);
      if(month<0||month>11||day<1||day>31)return;
      const year=rollYear(month,day,m[3]);
      results.push({title:titleFrom(line),date:year+"-"+String(month+1).padStart(2,"0")+"-"+String(day).padStart(2,"0"),kind:kindFrom(line),confidence:"low"});
    }
  });
  return results;
}
// Deterministic "never dead-end" fallback for the Brain Dump parser (see
// parseBrainDump in CalendarTab) — splits on commas/newlines/" and " and
// treats every fragment as a plain to-do. Deliberately never guesses a
// study duration here: without the AI actually reading the text, inventing
// a number would be a worse failure mode than just asking the student to
// schedule it themselves via the checklist.
// confidence:"low" on every item -- same convention regexScanDeadlines (the
// syllabus scan's own dumb fallback, above) already uses: a plain comma/
// "and" split has no real understanding of what it's looking at, so every
// item it produces is a guess, not just the ones parseBrainDump itself
// flagged. Surfaced in the review screen as the same "Low confidence,
// double-check" badge a syllabus scan's low-confidence items already get.
function fallbackSplitBrainDump(text){
  return (text||"")
    .split(/[,\n]|(?:\s+and\s+)/i)
    .map(s=>s.trim().replace(/^[\s\-*•.]+/,""))
    .filter(s=>s.length>2)
    .slice(0,15)
    .map(s=>({title:s.charAt(0).toUpperCase()+s.slice(1),kind:"todo",durationMin:null,dueDate:null,needsDuration:false,confidence:"low"}));
}
// Levels map strictly to real Lock-In Timer minutes — no streak/login/task
// bonuses, no penalty deductions, no starting offset. An honest sum of
// every session actually logged, nothing else.
function getTotalMinutesFocused(){
  const s=lsGet("sessions",[]);
  return s.reduce((acc,x)=>acc+(x.m||0),0);
}
// "Streak reminders" in Settings used to be a toggle with no engine behind
// it at all -- "a nudge if you haven't studied by 8pm" described a feature
// that didn't exist anywhere in the codebase (see S2 in the audit). Pure
// decision so it's testable without faking Notification/timers/clock: given
// the current hour, whether today's nudge already went out, and today's
// logged sessions, decides whether to fire one right now.
function shouldFireStreakNudge(hour,alreadySentToday,todaySessions){
  if(alreadySentToday)return false;
  if(hour<20)return false;
  if((todaySessions||[]).some(s=>(s.m||0)>0))return false;
  return true;
}
const getStreakNudgeSentDate=()=>lsGet("streak-nudge-sent-date",null);
const markStreakNudgeSent=(dateKey)=>lsSet("streak-nudge-sent-date",dateKey);
// "Deadline alerts" was the same story -- a toggle nothing read, so there
// was no way to say "only notify me about exams/assignments" the way the
// audit's S2 finding put it. Scoped narrowly: due-date kinds need this
// toggle on; every other kind's start-time reminder is unaffected by it,
// still gated only by the master switch exactly as before.
function reminderCategoryAllowed(evKind,deadlineAlertsOn){
  if(evKind==="deadline"||evKind==="exam")return deadlineAlertsOn!==false;
  return true;
}
// N9/N10 in the audit: this used to compute a real per-task XP penalty
// and accumulate it into xpPenaltyTotal on every load, with penalizedTasks
// growing by one entry per overdue task forever, no cleanup -- but
// nothing anywhere (levelInfo, profileStats) ever actually read
// xpPenaltyTotal, so the computation was pure overhead with zero visible
// effect. Actually making it punish students would be a real product
// decision (Studlin's whole brand personality is motivating, not
// punishing -- see CLAUDE.md), not something to decide unilaterally here,
// so removed rather than wired up. cleanupOrphanedPenaltyStorage (called
// once below) clears out what already accumulated in existing accounts.
function cleanupOrphanedPenaltyStorage(){
  if(lsGet("penaltyStorageCleaned",false))return;
  try{localStorage.removeItem("studlin-xpPenaltyTotal");localStorage.removeItem("studlin-penalizedTasks");}catch(e){}
  lsSet("penaltyStorageCleaned",true);
}
function levelInfo(){const minutes=getTotalMinutesFocused();const per=300;const level=Math.floor(minutes/per)+1;const into=minutes-(level-1)*per;const title=getProfTitle(minutes);const nextTier=PROF_TIERS.find(t=>t.minMinutes>minutes)||null;const curTierMinutes=(PROF_TIERS.slice().reverse().find(t=>minutes>=t.minMinutes)||PROF_TIERS[0]).minMinutes;const tierPct=nextTier?Math.round(Math.max(0,Math.min(100,(minutes-curTierMinutes)/(nextTier.minMinutes-curTierMinutes)*100))):100;return {minutes,level,into,per,toNext:per-into,pct:Math.round(into/per*100),title,nextTier,tierPct};}
function weekStreak(){const days=new Set(lsGet("days",[]));const now=new Date();const dow=(now.getDay()+6)%7;const mon=new Date(now);mon.setDate(now.getDate()-dow);return ["M","T","W","T","F","S","S"].map((lab,i)=>{const d=new Date(mon);d.setDate(mon.getDate()+i);const k=dayKey(d);const today=k===dayKey(now);return {lab,on:days.has(k),today,future:d>now&&!today};});}
// ─── ADVANCED SCHEDULING SYSTEM (5 features integrated) ──────────────────────
// Feature 1: User preference storage + getters/setters (complete with all onboarding preferences)
function getSchedulePreferences(){
  const def={
    workStartTime:"10:00",
    workEndTime:"18:00",
    bedtime:"23:00",
    // The real, UI-wired difficulty preference (Settings, the onboarding
    // wizard) — "easyFirst"/"balanced"/"hardFirst", read by scoreTask.
    // taskDifficultyPreference below is a separate, older key ("FIRST"/
    // "LAST"/"NONE") that nothing in the UI writes anymore; kept only so
    // legacy stored prefs objects don't lose the field, not read by any
    // live scoring path.
    difficultyPreference:"balanced",
    taskDifficultyPreference:"NONE",
    bufferMarginStrategy:"15_MIN",
    // Optional separate Sat/Sun hours — off by default, so every existing
    // account keeps its current single-window behavior until someone
    // explicitly turns this on in Settings.
    weekendEnabled:false,
    weekendStartTime:"10:00",
    weekendEndTime:"18:00",
    // Student-declared peak-focus buckets (TIER0_HOUR_BUCKETS ids). Opt-in,
    // empty by default — Tier 0 only special-cases a bucket here if the
    // student explicitly added it; this is never inferred on its own.
    peakHourBuckets:[],
    // "off"/"short"/"medium"/"long" -- see effectiveLeadInForManualPlacement/
    // effectiveTrailOutForManualPlacement's own comment for the full
    // reasoning. Defaults to "off": a manual placement (drag/drop, a
    // hand-typed Add Task time) trusts only a real literal time overlap
    // and real declared commuteBefore/commuteAfter unless a student
    // deliberately opts into a guessed cushion here too.
    manualBufferMode:"off",
    // See effectiveLeadIn/effectiveTrailOut's own comment -- defaults to
    // true (today's original, unconditional behavior) since automated
    // scheduling has no eyes of its own to notice a schedule packed
    // second-to-second the way a student placing one task manually can.
    automatedBufferEnabled:true,
  };
  const stored=lsGet("schedulePrefs",def);
  return {...def,...stored};
}
// Proportional Breathing Room — replaces the old fixed 3-tier break buckets
// with one continuous formula, anchored close to the previous tiers
// (25min->5, 60min->10, 90min->15) but still scaling past 120min instead of
// plateauing there. Used both as the Lock-In Timer's default break length
// and as a trailing buffer after existing blocks during gap-finding.
function computeBreathingRoom(mins){
  return Math.max(5,Math.min(20,Math.round((mins*0.15)/5)*5));
}
function setSchedulePreferences(prefs){
  lsSet("schedulePrefs",prefs);
}
// The one write step for the Calendar wizard's optional "personalize" step
// (5 single-select preference chips -- session order, interleaving
// tolerance, planning horizon, start timing, collision tie-break). Each
// stays null if the student skipped/never answered that one -- same
// "always present, individually empty" convention peakHourBuckets already
// uses, not an all-or-nothing object that's sometimes absent. Collection
// only: nothing in the placement/priority engine reads studyStylePrefs
// yet -- that's real, separate follow-up work (the collisionPref answer in
// particular is worded to match the exam-clustering priority signal
// discussed separately, so it has a real preference to read once that
// lands).
function applyStudyStylePrefs(prefs,answers){
  return {...prefs,studyStylePrefs:{
    sessionOrder:(answers&&answers.sessionOrder)||null,
    interleave:(answers&&answers.interleave)||null,
    planningHorizon:(answers&&answers.planningHorizon)||null,
    startTiming:(answers&&answers.startTiming)||null,
    collisionPref:(answers&&answers.collisionPref)||null,
  }};
}
// The first real consumer of studyStylePrefs.sessionOrder (the Calendar
// wizard's "hardest first" / "warm up first" personalize-step question --
// collected but unused until now). Deliberately narrow and safe: this
// never picks a NEW time slot and never touches findReliableSlotFor/
// findSlotWithEviction at all -- every session passed in already has a
// real, legally-placed `time` from whatever generated it (buildExamSessionEvents
// via planBrainDumpTasks, here). All this does is REASSIGN which
// already-legal time, among sessions landing on the SAME day, goes to
// which session -- ranked by difficulty. A day with 0-1 sessions, or a
// null/"no_preference" pref, is untouched. Because it only ever
// redistributes times that were already independently proven legal for
// that day, it can't introduce a conflict or violate a deadline that
// wasn't already possible before this ran.
function applySessionOrderPreference(sessions,sessionOrderPref){
  if(!sessionOrderPref||sessionOrderPref==="no_preference")return sessions;
  const byDate={};
  sessions.forEach(s=>{if(!s.time||!s.date)return;(byDate[s.date]=byDate[s.date]||[]).push(s);});
  const reassignedTime={};
  Object.values(byDate).forEach(dayGroup=>{
    if(dayGroup.length<2)return;
    const times=[...dayGroup].map(s=>s.time).sort();
    const byDifficulty=[...dayGroup].sort((a,b)=>{
      const da=a.difficulty||500,db=b.difficulty||500;
      return sessionOrderPref==="hardest_first"?db-da:da-db;
    });
    byDifficulty.forEach((s,i)=>{reassignedTime[s.id]=times[i];});
  });
  return sessions.map(s=>reassignedTime[s.id]?{...s,time:reassignedTime[s.id]}:s);
}

// Helper: convert "HH:MM" to minutes since midnight
function timeToMinutes(timeStr){
  if(!timeStr)return 0;
  const [h,m]=timeStr.split(":").map(Number);
  return h*60+m;
}

// Helper: convert minutes since midnight back to "HH:MM"
// Clamped, never wrapped: a caller that overflows past end-of-day (a late
// catch-up window colliding with a near-midnight workEndTime, or "now"
// itself sitting within ~15min of midnight) gets an honestly-late 23:59,
// never a silent wrap into tomorrow's early morning that would look like
// an unrelated slot on the same date, and never an invalid "24:xx"/"25:xx"
// string (see fmtClock12's own guard, and the reminder-notification effect's
// `new Date(ev.date+"T"+ev.time)`, both of which mis-handle that).
function minutesToTime(mins){
  const clamped=Math.max(0,Math.min(1439,Math.round(mins)));
  const h=Math.floor(clamped/60);
  const m=clamped%60;
  return String(h).padStart(2,"0")+":"+String(m).padStart(2,"0");
}

// Normalize a stored priority/difficulty value to 0-1.
// New tasks (Phase 3+) store 0-1000; legacy tasks store 0-10.
function normalizeTaskVal(v,defaultVal){
  const n=v!=null?v:defaultVal;
  return n>10?n/1000:n/10;
}

// Weighted scoring formula (returns 0-1000 integer, higher = schedule sooner).
// W_priority=0.35, W_deadline=0.35, W_difficulty=0.20, W_streak=0.10
function scoreTask(task,prefs,streak){
  const p=normalizeTaskVal(task.priority,5);

  const rawDiff=task.difficulty!=null?task.difficulty:500;
  const d=normalizeTaskVal(rawDiff,5);

  let urgency=0.3;
  if(task.deadline){
    const h=(new Date(task.deadline+"T23:59:00").getTime()-Date.now())/3600000;
    if(h<=0)urgency=1.0;
    else if(h<=24)urgency=1.0;
    else if(h<=48)urgency=0.8;
    else if(h<=72)urgency=0.6;
    else urgency=Math.max(0.3,0.6-(h-72)/240);
  }

  // regression: this used to read prefs.taskDifficultyPreference ("FIRST"/
  // "LAST"/"NONE"), a key nothing in the UI ever writes -- Settings and the
  // onboarding wizard both save the student's Easy/Hard First choice as
  // prefs.difficultyPreference ("easyFirst"/"hardFirst"/"balanced"). The two
  // keys were never reconciled, so this weight silently sat at the neutral
  // 0.5 default for every account regardless of what was actually picked.
  const pref=(prefs&&prefs.difficultyPreference)||"balanced";
  const diffWeight=pref==="hardFirst"?d:pref==="easyFirst"?1-d:0.5;

  const streakBoost=(streak||0)>=3?1.0:0.0;

  const raw=0.35*p+0.35*urgency+0.20*diffWeight+0.10*streakBoost;
  return Math.round(Math.min(1,raw)*1000);
}

// Re-score and re-slot all pending flexible tasks on dateKey.
// Returns the full updated events array; does not persist.
function rebalanceDay(dateKey,allEvents,routines,prefs){
  const streak=getStreak();
  const isFixed=isLeadInFixed;
  // userPinned tasks (manually dragged, or hand-typed a time in Add Task /
  // Edit) are excluded from reshuffling the same way FIXED kinds are — they
  // still occupy their slot (fall into `rest`, still block other tasks from
  // landing on top of them) but the algorithm never picks them back up and
  // moves them again just because a new task got added to the day.
  // A duration-less deadline marker (a syllabus-scanned "this is due" fact,
  // not a real work block) isn't a FIXED kind — only kind:"exam" is — so
  // without this it would get pulled into the reshuffle, scored as
  // maximally urgent (its own deadline is its own date), and given a fake
  // 60-min footprint at the front of the day, potentially displacing real
  // study blocks. Same "no duration = fact, not a task" rule as isDuePill
  // in WeeklyPlanner and isTier0Missed's implicit same-day-deadline guard.
  // Fixed/checklist/done/pinned exclusions now live in the shared
  // isReorderableTask (also used by Today's Plan) -- this layers on the
  // two constraints specific to an actual reshuffle: must be today, and
  // must already be a real, duration-bearing work block.
  const isFlexPending=function(e){return e.date===dateKey&&e.time&&e.duration&&isReorderableTask(e);};

  const flex=allEvents.filter(isFlexPending);
  if(flex.length===0)return allEvents;

  const rest=allEvents.filter(function(e){return !isFlexPending(e);});

  const occupiedBase=rest.filter(function(e){return e.date===dateKey&&e.time&&!e.timeUnconfirmed&&e.status!=="done";}).map(function(e){
    return{start:timeToMinutes(e.time)-effectiveLeadIn(e),end:timeToMinutes(e.time)+(e.duration||30)+effectiveTrailOut(e)};
  });
  expandRoutineOccurrences(routines||[],dateKey,dateKey)
    .filter(function(r){return r.kind!=="free period";})
    .forEach(function(r){occupiedBase.push({start:timeToMinutes(r.time)-effectiveLeadIn(r),end:timeToMinutes(r.time)+(r.duration||30)+effectiveTrailOut(r)});});

  // With only one flexible task, there's nothing to reorder relative to —
  // leave it exactly where it is unless it's actually colliding with
  // something fixed/pinned it needs to route around (a pinned task now
  // occupying that exact slot, for instance).
  if(flex.length<2){
    const solo=flex[0];
    const soloStart=timeToMinutes(solo.time);
    const soloEnd=soloStart+(solo.duration||60);
    const collides=occupiedBase.some(function(o){return!(soloEnd<=o.start||soloStart>=o.end);});
    if(!collides)return allEvents;
  }

  const sorted=[...flex].sort(function(a,b){return scoreTask(b,prefs,streak)-scoreTask(a,prefs,streak);});

  const dayWindow=getWorkWindowMinsFor(prefs,dateKey);
  let prefStart=dayWindow.start;
  const prefEnd=dayWindow.end;
  const isToday=dateKey===dayKey();
  // Same "never re-slot into the past" floor as findOpenSlotFor — without
  // this, saving or editing any second task today silently snapped every
  // flexible task on the day back to workStartTime, clobbering times that
  // aiArrange/findOpenSlotFor had already correctly placed after "now".
  if(isToday){
    const now=new Date();
    const nowFloorMins=Math.ceil((now.getHours()*60+now.getMinutes()+15)/15)*15;
    prefStart=Math.max(prefStart,nowFloorMins);
  }
  // Same end-of-day catch-up buffer as findOpenSlotFor — a rebalance
  // triggered late in the day (e.g. adding a second task at 9pm) shouldn't
  // strand overflow tasks just because normal work hours are full. Capped
  // at 1440 (see findOpenSlotFor's matching cap) so a late workEndTime
  // preference can't push this past midnight into an invalid time.
  const dayEnd=isToday?Math.min(1440,prefEnd+CATCHUP_BUFFER_MINS):prefEnd;

  const occupied=occupiedBase.slice();

  const reassigned=sorted.map(function(task){
    const dur=task.duration||60;
    if(prefStart+dur>dayEnd)return task; // no room left even with the catch-up buffer — leave it where it was rather than force a slot
    for(let t=prefStart;t+dur<=dayEnd;t+=15){
      if(!occupied.some(function(o){return!(t+dur<=o.start||t>=o.end);})){
        occupied.push({start:t,end:t+dur+computeBreathingRoom(dur)});
        return Object.assign({},task,{time:minutesToTime(t)});
      }
    }
    return task;
  });

  return rest.concat(reassigned);
}

// "Balance my week" — manually triggered only, never automatic. Everything
// else that moves more than one task at once in this file (Tier 0, Studlin
// Reschedule) either acts on a single already-missed/already-targeted task
// or is explicitly requested for one specific day; silently redistributing
// several already-committed tasks across a whole week in the background
// would be the highest blast-radius thing this app does. Pure data in/out,
// same review-then-commit discipline as commitSyllabusEvents/confirmReview
// — nothing is written until the student picks specific moves and applies
// them from the review screen.
const WEEK_BALANCE_DAYS=7;
// A day only counts as "heavy" if it's meaningfully above the week's own
// average flexible-task load — avoids proposing a token 15-minute shuffle
// between two days that are already close to even.
const WEEK_BALANCE_HEAVY_THRESHOLD_MINS=45;
// "Heavy relative to average" is meaningless when the week barely has
// anything scheduled at all — one 60-minute task on an otherwise empty
// week trivially clears WEEK_BALANCE_HEAVY_THRESHOLD_MINS against a
// near-zero average, producing a technically-true but nonsensical "your
// week is lopsided" nudge for a single task. Require a real minimum
// amount of total flexible work in the window before "lopsided" is even
// a meaningful question to ask.
const WEEK_BALANCE_MIN_TOTAL_MINS=180;
// Hard backstop on the per-heavy-day while loop below -- there are at most
// WEEK_BALANCE_DAYS-1 other days a task could ever move to, so no single
// heavy day should legitimately need anywhere close to this many
// iterations to either empty out or run out of safely-movable candidates.
const WEEK_BALANCE_MAX_ITER=50;
// How much a target day's reliability (0-1, from getBucketReliability)
// can outweigh raw minutes-away-from-average when picking where a
// shed task lands -- treats a fully-reliable slot as worth up to 60
// "minutes lighter" than it actually is, enough to beat a merely-lighter
// but historically-unreliable day without ever fully overriding load
// balancing itself.
const REBALANCE_RELIABILITY_MINS_WEIGHT=60;
function computeWeekBalancePlan(events,routines,prefs,startDateKey){
  const days=[];
  for(let i=0;i<WEEK_BALANCE_DAYS;i++){
    const d=new Date(startDateKey+"T12:00:00");d.setDate(d.getDate()+i);
    days.push(dayKey(d));
  }
  // Same flexible-task definition rebalanceDay uses (isFlexPending above),
  // plus userPinned excluded the same way — a student who explicitly
  // pinned a task gets to keep it exactly where they put it, even here.
  // Routed through the shared isLeadInFixed (Phase 7b) instead of its own
  // local copy of the same TIER0_FIXED_KINDS||isCoopStudySession formula,
  // so a movable:true override on a fixed-kind item is respected here too.
  const isFlex=e=>!isLeadInFixed(e)&&!e.checklist&&e.status==="pending"&&e.time&&e.duration&&!e.userPinned;
  const minutesFor=(dk,pool)=>pool.filter(e=>e.date===dk&&isFlex(e)).reduce((sum,e)=>sum+(e.duration||0),0);

  const before={};
  days.forEach(dk=>{before[dk]=minutesFor(dk,events);});
  const avg=days.reduce((sum,dk)=>sum+before[dk],0)/days.length;
  const totalMins=days.reduce((sum,dk)=>sum+before[dk],0);

  // Heaviest day first, so the worst day gets first crack at shedding load.
  // No day is ever "heavy" at all when the week's total flexible load is
  // too small for "average" to mean anything (see WEEK_BALANCE_MIN_TOTAL_MINS).
  const heavyDays=totalMins<WEEK_BALANCE_MIN_TOTAL_MINS?[]:days.filter(dk=>before[dk]-avg>=WEEK_BALANCE_HEAVY_THRESHOLD_MINS).sort((a,b)=>before[b]-before[a]);

  let working=events.slice();
  const moves=[];
  heavyDays.forEach(heavyDk=>{
    // Recompute fresh — an earlier heavy day's move may have already
    // loaded this one up as a target, or already brought it back to average.
    // Real infinite-loop bug found live: this while loop's only exit
    // conditions were "no candidates" or "no target found" -- both assume
    // every successful move actually reduces heavyDk's load. WEEK_BALANCE_MAX_ITER
    // is a hard backstop in case that assumption is ever wrong for some
    // data shape this couldn't anticipate, so a scheduling edge case
    // freezes one nudge's computation instead of the whole app.
    let iter=0;
    while(minutesFor(heavyDk,working)-avg>=WEEK_BALANCE_HEAVY_THRESHOLD_MINS&&iter++<WEEK_BALANCE_MAX_ITER){
      // Same "safely movable" criteria findSlotWithEviction already trusts
      // for same-day eviction: real study blocks only, no imminent deadline
      // (more than a week out, or none at all) — never an exam, a fixed
      // commitment, or a task genuinely due soon.
      // Lowest priority first (sessions carry a real, current priority as
      // of computeSessionPriority/restampSessionPriorities), a per-move
      // penalty added on top so an already-reshuffled session needs a
      // bigger genuine priority gap to be picked again (see
      // RESHUFFLE_PENALTY), duration as the final tiebreak -- shed the
      // least important, least-already-disrupted thing on the day.
      // Anything that's crossed RESHUFFLE_ESCALATE_THRESHOLD is excluded
      // entirely rather than silently reshuffled again.
      const candidates=working.filter(e=>e.date===heavyDk&&isFlex(e)&&e.kind==="study block"&&(!e.deadline||daysUntilDeadline(e)>7)&&(e.reshuffleCount||0)<RESHUFFLE_ESCALATE_THRESHOLD)
        .sort((a,b)=>(((a.priority??500)+(a.reshuffleCount||0)*RESHUFFLE_PENALTY)-((b.priority??500)+(b.reshuffleCount||0)*RESHUFFLE_PENALTY))||((b.duration||0)-(a.duration||0)));
      if(candidates.length===0)break; // this day is heavy but nothing on it is safely movable
      const task=candidates[0];
      // Target the lightest OTHER day in the window that's also a
      // reliable time for this student -- reuses the exact bucket/tier
      // derivation findTier0Slot/findReliableSlotFor already use for
      // fresh placement (hourBucket+difficultyTierOf+getBucketReliability),
      // extended here so rebalancing doesn't just chase an empty calendar
      // slot while ignoring whether the student actually follows through
      // at that time. A day's own legal slot is computed once, up front,
      // for every candidate day (not just the eventual pick) so the
      // ranking can weigh mins-away-from-average against reliability
      // together instead of trying strictly-lightest-first and stopping
      // at the first day with room. Missing/insufficient reliability
      // sample (getBucketReliability returns null) is treated as neutral
      // (0.5) rather than penalizing a sparse-history account.
      const tier=difficultyTierOf(task);
      const targets=days.filter(dk=>dk!==heavyDk).map(dk=>{
        const slot=findLegalSlotOrNull(working.filter(e=>e.id!==task.id),routines,prefs,dk,prefs.workStartTime,task.duration,task.deadline||null);
        // Real infinite-loop bug found live: findLegalSlotOrNull's own
        // findOpenSlotFor scans up to 21 days FORWARD from `dk` looking for
        // an open slot, and can silently hand back a date that isn't `dk`
        // at all -- including, on a packed week, heavyDk itself. That
        // "moved" a task from heavyDk right back onto heavyDk: minutesFor
        // never dropped, the same candidate got picked again next
        // iteration, and the while loop above never terminated. A move
        // that doesn't actually land on the requested lighter day isn't a
        // real move.
        if(!slot||slot.date!==dk)return null;
        const reliability=getBucketReliability(hourBucket(slot.time),tier)??0.5;
        return {dk,mins:minutesFor(dk,working),slot,reliability};
      }).filter(Boolean).sort((a,b)=>(a.mins-a.reliability*REBALANCE_RELIABILITY_MINS_WEIGHT)-(b.mins-b.reliability*REBALANCE_RELIABILITY_MINS_WEIGHT));
      let moved=false;
      if(targets.length>0){
        const t=targets[0];
        working=working.map(e=>e.id===task.id?{...e,date:t.slot.date,time:t.slot.time}:e);
        // Plain and factual, same "state the fact" convention this file's
        // other student-facing reason copy already follows -- this answers
        // "why THIS task got picked to move," a different question from
        // fmtPlacementReason's "why THIS time slot."
        const reason="Moved off "+heavyDk+" ("+Math.round(before[heavyDk])+" min of flexible work that day, above your "+Math.round(avg)+" min average). The lowest priority item scheduled that day.";
        moves.push({id:task.id,title:task.title,duration:task.duration,fromDate:task.date,fromTime:task.time,toDate:t.slot.date,toTime:t.slot.time,reason});
        moved=true;
      }
      // No legal day anywhere in the window for this specific task — drop
      // just this one candidate and stop trying this heavy day rather than
      // looping on the same unmovable task forever.
      if(!moved)break;
    }
  });

  const perDay=days.map(dk=>({date:dk,minutesBefore:before[dk],minutesAfter:minutesFor(dk,working)}));
  return {moves,perDay};
}
// Proactive nudge toward the (already-real, preview-then-confirm) "Balance
// my week" flow above — that flow was manual-trigger-only, so a student
// had to remember it exists. Single cooldown timestamp (not per-bucket
// like detectStrugglingBucket/detectPeakHourInsight) since there's only
// one week to balance, not several independent buckets. Shorter cooldown
// than those two (3 days, not 14) since "is this week heavy" is a
// week-scoped question that goes stale fast — a dismissal shouldn't
// silence it deep into a different, genuinely-overloaded week.
const WEEK_BALANCE_NUDGE_COOLDOWN_MS=3*86400000;
function shouldShowWeekBalanceNudge(){
  const dismissedAt=lsGet("weekBalanceNudgeDismissedAt",0);
  return Date.now()-dismissedAt>=WEEK_BALANCE_NUDGE_COOLDOWN_MS;
}
function dismissWeekBalanceNudge(){
  lsSet("weekBalanceNudgeDismissedAt",Date.now());
}
// "Scan my whole schedule" (college) and the HS bulk-schedule import both
// read a schedule GRID -- class names + meeting times, plus any exam dates
// that happen to be printed on it. Neither can pull assignments/projects,
// because a schedule grid genuinely doesn't contain them (that's a
// syllabus, a different document). Subjects created either way are tagged
// needsSyllabus so a nudge can point back at the same quickScan+
// targetCourseId "Import syllabus"/"Scan assignments" flow already
// reachable from each course's own menu, instead of leaving assignments
// as a dead end with no path back except manual entry. Cooldown (not
// permanent dismiss) since new bulk-scanned classes can show up later and
// still deserve the nudge, same reasoning as shouldShowWeekBalanceNudge above.
const SYLLABUS_NUDGE_COOLDOWN_MS=3*86400000;
function shouldShowSyllabusNudge(){
  const dismissedAt=lsGet("syllabusNudgeDismissedAt",0);
  return Date.now()-dismissedAt>=SYLLABUS_NUDGE_COOLDOWN_MS;
}
function dismissSyllabusNudge(){
  lsSet("syllabusNudgeDismissedAt",Date.now());
}
// A class only needs the nudge if nothing it was given so far actually
// came from a syllabus -- exam-only items (all a schedule-grid scan can
// ever produce) or no items at all (a manually "choose"-added class)
// both still qualify; a real syllabus scan's assignment/project items
// satisfy it, whichever flow originally produced them.
function classNeedsSyllabus(items){
  return !(items||[]).some(it=>it.kind==="assignment"||it.kind==="project");
}

// Studlin Reschedule's actual planning engine ("push everything back N
// days" / "clear this day" / "clear this week" / "skip class today").
// Lives at module scope (not inside CalendarTab, where it originally sat)
// because it never actually closed over any component-local state — every
// dependency (dayKey, getWeeklyRoutine, getSchedulePreferences, lsGet,
// findLegalSlotOrNull) is already module-level, so moving it here is a
// pure relocation with no behavior change. Two things that make this worth
// doing: it's testable in isolation now, and it's the exact function where
// a real bug was found and fixed (a duration-less due-date marker could
// have its actual due date moved by these commands — see isQualifying's
// carve-out below).
const PAUSE_QUALIFYING_KINDS=new Set(["study block","deadline","reminder"]);
// A syllabus-scanned due-date marker is kind:"deadline" but duration:null (a
// real assignment's own scheduled work block always has a real duration) —
// without this carve-out, "push everything back"/"clear this week"/a class
// skip would move the actual due date itself, which is a fact set by the
// professor, not student time Studlin is free to reschedule. Reminders keep
// duration:0 by design (a point-in-time nudge, not a block) and are
// legitimately reschedulable, so this only excludes "deadline" specifically,
// not the whole qualifying set. !ev.checklist mirrors isTier0Missed's own
// exclusion — a checklist item is a plain to-do with no inherent time and
// must never be assigned one, here just as much as during Tier 0's rollover.
// Module scope (not a closure inside computePausePlan) since
// computeClassSkipPlan needs it too.
const isQualifying=(ev)=>ev.status==="pending"&&PAUSE_QUALIFYING_KINDS.has(ev.kind)&&!(ev.kind==="deadline"&&ev.duration==null)&&!ev.checklist;
// Shared by the "skip_class" Tier-3 intent (skips every class-kind routine
// matching a weekday) and a single-occurrence skip triggered directly from
// the calendar UI (skips exactly one routineId) — both just need to hand in
// the routine id(s) already decided to be skipped and the date, and get back
// a computePausePlan-shaped preview so the same modal renders either one
// with no changes.
function computeClassSkipPlan(skippedIds,date){
  const routinesAll=getWeeklyRoutine();
  const label=skippedIds.length===0?"No class scheduled "+date:"Skip class, "+date;
  if(skippedIds.length===0)return{label,moved:[],couldntMove:[],skipRoutine:null};
  // Preview the freed slot without touching localStorage yet — pass a
  // routines list with the skipped rule(s) filtered out, same idea as
  // Tier 3's other intents computing entirely in-memory until Confirm. The
  // actual persisted skip (which every other scheduler in the app also
  // needs to see, not just this preview) only gets written in
  // confirmPausePlan.
  const routinesMinusSkipped=routinesAll.filter(r=>!skippedIds.includes(r.id));
  const prefsNow=getSchedulePreferences();
  const all=lsGet("events",[]);
  const candidates=all.filter(ev=>isQualifying(ev)&&ev.date>date)
    .sort((a,b)=>a.date===b.date?((a.time||"")<(b.time||"")?-1:1):(a.date<b.date?-1:1));
  let working=all;
  const moved=[];
  for(const ev of candidates){
    if(moved.length>=4)break;
    const slot=findLegalSlotOrNull(working.filter(e=>e.id!==ev.id),routinesMinusSkipped,prefsNow,date,prefsNow.workStartTime,ev.duration||30,ev.deadline||null);
    if(slot&&slot.date===date){
      moved.push({id:ev.id,title:ev.title,oldDate:ev.date,oldTime:ev.time,newDate:slot.date,newTime:slot.time});
      working=working.map(e=>e.id===ev.id?{...e,date:slot.date,time:slot.time}:e);
    }
  }
  return{label,moved,couldntMove:[],skipRoutine:{date,routineIds:skippedIds}};
}
// Suggests up to 3 pending qualifying tasks that would fit into a
// specific just-freed window (e.g. after deleting an event from the
// Weekly grid's Backspace shortcut) — deliberately simpler than the
// forward-scanning slot finders above: the window is already known and
// already empty (nothing else could have moved into it yet), so this
// only needs a straight duration-fits check and a soonest-deadline-first
// sort, not a search. Pure/no side effects — the caller decides
// whether/how to actually place one.
function computeFillSuggestions(freedDate,freedTime,freedDuration){
  // A freed slot on a day that's already fully in the past (deleting a
  // stale, never-done task still sitting on an earlier day) isn't
  // something to fill retroactively either -- 2026-08-25 regression: this
  // used to only check "today, but the time already elapsed," silently
  // assuming freedDate could never actually be BEFORE today. It very much
  // can (a Backspace/Delete on any old leftover item), and prompting "Fill
  // 10:00 AM on Mon, Aug 24?" while it's actually Tuesday the 25th read as
  // Studlin not knowing what day it is.
  if(freedDate<dayKey())return [];
  // A freed slot earlier today that's already elapsed isn't something to
  // fill retroactively -- deleting an 8am task while it's actually 6pm
  // shouldn't prompt "Fill 8:00 AM?". Only checked for TODAY; a freed slot
  // on a future date is always still fillable regardless of the current
  // clock.
  const nowMins=(()=>{const n=new Date();return n.getHours()*60+n.getMinutes();})();
  if(freedDate===dayKey()&&timeToMinutes(freedTime)+freedDuration<=nowMins)return [];
  const all=lsGet("events",[]);
  // Reminders are point-in-time nudges with duration:0 by design (see
  // isQualifying's own comment above) -- legitimately reschedulable by the
  // pause-plan engine, but nonsensical as a "put this in the freed work
  // slot" suggestion here, since they have no real duration to occupy.
  // Excluded locally rather than from isQualifying/PAUSE_QUALIFYING_KINDS
  // itself, which the pause-plan engine still needs reminders in. Once
  // reminders are out, no remaining qualifying kind has duration:0, so the
  // old `ev.duration||30` fallback is dropped too -- it was silently
  // turning a reminder's real duration:0 into 30, which is exactly what
  // let a reminder pass the size check and get suggested here at all.
  return all.filter(ev=>isQualifying(ev)&&ev.kind!=="reminder"&&ev.date>=freedDate&&ev.duration<=freedDuration)
    .sort((a,b)=>{
      const da=a.deadline||"9999-99-99",db=b.deadline||"9999-99-99";
      return da<db?-1:da>db?1:0;
    })
    .slice(0,3)
    .map(ev=>({id:ev.id,title:ev.title,duration:ev.duration}));
}
// Exam-stakes-aware ranking for computePausePlan's shift/clear_day/
// clear_week reslotting below -- an exam-prep session looks up its real
// exam and scores off computeSessionPriority's full urgency/impact/
// confidence/difficulty blend (the same score already stamped onto the
// session and kept fresh by restampSessionPriorities); anything else
// (a plain deadline/reminder with no dueEventId) scores off its own
// fields, which is still a meaningful urgency+difficulty signal even
// without exam-specific impact data. Without this, a slot race during a
// busy reshuffle is won by whichever qualifying event simply comes first
// on the clock, not by which one actually matters more.
function sessionPriorityFor(ev,pool){
  const exam=ev.dueEventId?pool.find(e=>e.id===ev.dueEventId&&e.kind==="exam"):null;
  return computeSessionPriority(exam||ev,dayKey());
}
function computePausePlan(intent,forcedId){
  const today=dayKey();
  if(intent.intent==="move_event"||intent.intent==="retime_event"){
    const targetDate=intent.targetDate||today;
    let matched;
    if(forcedId){
      // Re-entry after the student picked one of several disambiguation
      // candidates — skip fuzzy matching entirely and look the exact id up
      // in the same pool matchEventByTitle would have searched.
      const pool=lsGet("events",[]).filter(ev=>ev.date===targetDate).concat(getRoutineOccurrencesForDate(targetDate));
      matched=pool.find(ev=>ev.id===forcedId)||null;
      if(!matched)return{label:"That event isn't on the calendar anymore",moved:[],couldntMove:[],noMatch:true};
    }else{
      const{matches}=matchEventByTitle(intent.target||"",targetDate);
      if(matches.length===0)return{label:"Couldn't find \""+(intent.target||"")+"\" on "+targetDate,moved:[],couldntMove:[],noMatch:true};
      if(matches.length>1)return{label:"Which one did you mean?",moved:[],couldntMove:[],disambiguate:matches.map(ev=>({id:ev.id,title:ev.title,date:ev.date,time:ev.time,isRoutine:!!ev.isRoutine,routineId:ev.routineId||null}))};
      matched=matches[0];
    }
    const all=lsGet("events",[]);
    const routinesNow=getWeeklyRoutine();
    const prefsNow=getSchedulePreferences();
    if(intent.intent==="move_event"){
      // No destination day named ("make it sometime") defaults to tomorrow,
      // not today — the student just said they can't make the original
      // slot, so offering that exact slot straight back would be wrong.
      const dest=intent.destDate||dayKey(new Date(new Date(matched.date+"T12:00:00").getTime()+86400000));
      const workingEvents=all.filter(e=>e.id!==matched.id);
      // If matched is a routine occurrence, its own rule is still active
      // (skip_class hasn't been applied — that only happens on Confirm) and
      // would otherwise self-collide with the search on any day it also
      // recurs on (e.g. moving a daily habit-adjacent class, or a
      // Mon/Wed/Fri class to another day it meets), falling all the way
      // through to the last-resort scan and landing at midnight. Excluding
      // the rule here mirrors skip_class's own routinesMinusSkipped pattern.
      const routinesForSearch=matched.isRoutine?routinesNow.filter(r=>r.id!==matched.routineId):routinesNow;
      const slot=findFixedEventSlot(workingEvents,routinesForSearch,prefsNow,dest,matched.time||"09:00",matched.duration||30);
      const moved=[{id:matched.id,title:matched.title,oldDate:matched.date,oldTime:matched.time,newDate:slot.date,newTime:slot.time,newDuration:matched.duration||30,isRoutine:!!matched.isRoutine,routineId:matched.routineId||null,kind:matched.kind,subject:matched.subject||""}];
      return{label:"Move "+matched.title,moved,couldntMove:[]};
    }
    // retime_event: figure out who else on targetDate now collides with the
    // event's new time window and reslot just those, leaving everything
    // else untouched.
    const newStart=intent.newStart;
    const newDuration=intent.newDuration||matched.duration||30;
    const newStartMins=timeToMinutes(newStart);
    const newEndMins=newStartMins+newDuration;
    const sameDayOthers=all.filter(e=>e.date===targetDate&&e.id!==matched.id)
      .concat(getRoutineOccurrencesForDate(targetDate).filter(o=>o.id!==matched.id));
    const displaced=sameDayOthers.filter(ev=>{
      if(!isQualifying(ev)||!ev.time)return false;
      const s=timeToMinutes(ev.time),e=s+(ev.duration||30);
      return !(newEndMins<=s||newStartMins>=e);
    }).sort((a,b)=>(a.time||"")<(b.time||"")?-1:1);
    // Drop the retimed item's own old-time entry (a no-op if it's a routine
    // occurrence, which was never in `events`) and every displaced item,
    // then stand in a synthetic block at the NEW time so nothing gets
    // reslotted on top of it. Note: if the retimed item is a routine
    // occurrence, its OLD-time slot still shows as occupied to the slot
    // finder (the routine rule itself isn't touched until Confirm), which
    // only makes reslotting slightly more conservative — it just won't
    // offer displaced tasks the now-freed old slot, never a double-booking.
    let working=all.filter(e=>e.id!==matched.id&&!displaced.some(d=>d.id===e.id))
      .concat([{id:"__retimed__"+matched.id,date:targetDate,time:newStart,duration:newDuration,kind:matched.kind||"busy block",status:"pending"}]);
    const moved=[{id:matched.id,title:matched.title,oldDate:matched.date,oldTime:matched.time,newDate:targetDate,newTime:newStart,newDuration,isRoutine:!!matched.isRoutine,routineId:matched.routineId||null,kind:matched.kind,subject:matched.subject||""}];
    const couldntMove=[];
    displaced.forEach(ev=>{
      const slot=findLegalSlotOrNull(working,routinesNow,prefsNow,ev.date,ev.time,ev.duration||30,ev.deadline||null);
      if(!slot){couldntMove.push({id:ev.id,title:ev.title,deadline:ev.deadline||null});return;}
      moved.push({id:ev.id,title:ev.title,oldDate:ev.date,oldTime:ev.time,newDate:slot.date,newTime:slot.time});
      working=working.concat([{...ev,date:slot.date,time:slot.time}]);
    });
    return{label:"Retime "+matched.title,moved,couldntMove};
  }
  if(intent.intent==="skip_class"){
    const date=intent.date||today;
    const dow=(new Date(date+"T12:00:00").getDay()+6)%7;
    const skippedIds=getWeeklyRoutine().filter(r=>r.kind==="class"&&r.days&&r.days.includes(dow)).map(r=>r.id);
    return computeClassSkipPlan(skippedIds,date);
  }
  let label,inWindow,computeNewDate;
  if(intent.intent==="shift"){
    const days=Math.max(1,Math.min(14,intent.days||1));
    label="Push everything back "+days+" day"+(days!==1?"s":"");
    inWindow=(ev)=>isQualifying(ev)&&ev.date>=today;
    computeNewDate=(ev)=>{const d=new Date(ev.date+"T12:00:00");d.setDate(d.getDate()+days);return dayKey(d);};
  }else if(intent.intent==="clear_day"){
    const date=intent.date||today;
    label="Clear "+date;
    inWindow=(ev)=>isQualifying(ev)&&ev.date===date;
    computeNewDate=()=>{const d=new Date(date+"T12:00:00");d.setDate(d.getDate()+1);return dayKey(d);};
  }else{
    const end=(()=>{const d=new Date();d.setDate(d.getDate()+6);return dayKey(d);})();
    label="Clear this week";
    inWindow=(ev)=>isQualifying(ev)&&ev.date>=today&&ev.date<=end;
    computeNewDate=()=>{const d=new Date();d.setDate(d.getDate()+7);return dayKey(d);};
  }
  const all=lsGet("events",[]);
  const routinesNow=getWeeklyRoutine();
  const prefsNow=getSchedulePreferences();
  // Higher-stakes items (a final's last prep session) claim scarce slots
  // before lower-stakes ones (a flashcard review) -- see sessionPriorityFor.
  // Same date/time order as before is kept only as the tiebreaker.
  const affected=all.filter(inWindow).sort((a,b)=>{
    const pa=sessionPriorityFor(a,all),pb=sessionPriorityFor(b,all);
    if(pa!==pb)return pb-pa;
    return a.date===b.date?((a.time||"")<(b.time||"")?-1:1):(a.date<b.date?-1:1);
  });
  let working=all.filter(ev=>!inWindow(ev));
  const moved=[],couldntMove=[];
  affected.forEach(ev=>{
    const desiredDate=computeNewDate(ev);
    const slot=findLegalSlotOrNull(working,routinesNow,prefsNow,desiredDate,ev.time||prefsNow.workStartTime,ev.duration||30,ev.deadline||null);
    if(slot){
      moved.push({id:ev.id,title:ev.title,oldDate:ev.date,oldTime:ev.time,newDate:slot.date,newTime:slot.time});
      working=working.concat([{...ev,date:slot.date,time:slot.time}]);
    }else{
      // Flag it distinctly when the un-reschedulable item is prep for a
      // high-stakes exam (major/critical importance, or close enough that
      // CATCHUP_EXAM_URGENT_DAYS already treats it as time-sensitive
      // elsewhere) so the student sees this BEFORE confirming, not after --
      // see the Reschedule preview's couldntMove rendering.
      const linkedExam=ev.dueEventId?all.find(e=>e.id===ev.dueEventId&&e.kind==="exam"):null;
      let examWarning=null;
      if(linkedExam){
        const daysUntilExam=Math.round((new Date(linkedExam.date+"T12:00:00")-new Date(today+"T12:00:00"))/86400000);
        const highStakes=linkedExam.importanceLevel==="major"||linkedExam.importanceLevel==="critical";
        if(highStakes||(daysUntilExam>=0&&daysUntilExam<=CATCHUP_EXAM_URGENT_DAYS)){
          examWarning={examTitle:linkedExam.title,daysUntilExam};
        }
      }
      couldntMove.push({id:ev.id,title:ev.title,deadline:ev.deadline,examWarning});
      working=working.concat([ev]);
    }
  });
  return {label,moved,couldntMove};
}
// ── Studlin AI Phase 2: action proposals (create/move via chat) ────────────
// Routes a classified chat message (see classifyStudlinAiMessage, near
// StudlinAiDrawer below) into a concrete, previewable proposal before
// anything is ever written -- split into three thin builders so each
// write-path's real safety boundary stays visible and independently
// testable:
//   - buildMoveFixedProposal: fixed real-world commitments (class/
//     practice/appointment) and the whole-schedule bulk intents -- calls
//     computePausePlan completely unchanged.
//   - buildMoveFlexTaskProposal: ONE flexible, deadline-bearing item (a
//     study block/deadline/reminder) -- deliberately its own intent
//     (move_flex_task), never routed through computePausePlan's
//     move_event, which calls findFixedEventSlot -- a deadline-blind
//     slot finder meant only for fixed commitments (see its own comment
//     a few hundred lines up). findLegalSlotOrNull (the same Hard Wall
//     primitive shift/clear_day/retime_event already trust) is the
//     correct primitive for a task that has its own deadline and work-
//     hour constraints to respect.
//   - buildCreateTaskProposal: wraps planBrainDumpTasks at single-item
//     granularity, the exact call shape expandBrainDumpItem (CalendarTab)
//     already proves safe and reusable.
// All three are pure -- no lsSet, no write -- matching computePausePlan/
// planBrainDumpTasks' own "preview only" contract, so nothing commits
// before the student explicitly confirms (see commitStudlinAiTasks/
// commitStudlinAiFixedMove/commitStudlinAiFlexMove below for the actual
// writes, called only from StudlinAiDrawer's Confirm handler).
function buildMoveFixedProposal(parsed,forcedId){
  return computePausePlan(parsed,forcedId);
}
// Reuses isQualifying/PAUSE_QUALIFYING_KINDS -- the exact same "is this a
// flexible, movable, non-fact item" definition the pause-plan engine
// itself already established (excludes a real due-date fact, a checklist
// item, anything not pending), rather than inventing a second one here.
function buildMoveFlexTaskProposal(parsed,events,routines,prefs,forcedId){
  const targetDate=parsed.targetDate||dayKey();
  let matched;
  if(forcedId){
    const pool=events.filter(ev=>ev.date===targetDate).concat(getRoutineOccurrencesForDate(targetDate));
    matched=pool.find(ev=>ev.id===forcedId)||null;
    if(!matched)return{label:"That task isn't on the calendar anymore",moved:[],couldntMove:[],noMatch:true};
  }else{
    const{matches}=matchEventByTitle(parsed.target||"",targetDate);
    const flexMatches=matches.filter(m=>!m.isRoutine&&isQualifying(m));
    if(flexMatches.length===0)return{label:"Couldn't find \""+(parsed.target||"")+"\" on "+targetDate,moved:[],couldntMove:[],noMatch:true};
    if(flexMatches.length>1)return{label:"Which one did you mean?",moved:[],couldntMove:[],disambiguate:flexMatches.map(ev=>({id:ev.id,title:ev.title,date:ev.date,time:ev.time}))};
    matched=flexMatches[0];
  }
  const destDate=parsed.destDate||dayKey(new Date(new Date(targetDate+"T12:00:00").getTime()+86400000));
  const others=events.filter(e=>e.id!==matched.id);
  const slot=findLegalSlotOrNull(others,routines,prefs,destDate,matched.time||prefs.workStartTime,matched.duration||30,matched.deadline||null);
  if(!slot)return{label:"No open, on-time slot for \""+matched.title+"\" on or before its deadline",moved:[],couldntMove:[{id:matched.id,title:matched.title,deadline:matched.deadline||null}]};
  return{label:"Move "+matched.title,moved:[{id:matched.id,title:matched.title,oldDate:matched.date,oldTime:matched.time,newDate:slot.date,newTime:slot.time,duration:matched.duration||30}],couldntMove:[]};
}
// Small pure formatter for the proposal card's label text -- mirrors
// computePausePlan's own plain-English `label` field so create and move
// proposals both read the same way in the drawer.
function describeCreateProposal(task){
  if(!task)return"Add task";
  const when=task.time?(task.date+" "+task.time+(task.duration?" ("+task.duration+" min)":"")):(task.date?"due "+task.date:"no date yet");
  return"Add \""+task.title+"\" -- "+when+"?";
}
// Bug fix, 2026-09-04 audit: every proposal.label above is phrased as a
// pre-confirm question ("Delete \"X\" from date?", "Add \"Y\" -- when?")
// -- confirmProposal used to reuse it verbatim in the post-confirm "Done."
// message, so the chat literally said e.g. "Done. Delete "Chem Notes"
// from 2026-09-08?" even though the action had already finished. Strips
// the trailing "?" and turns the leading imperative into a completed one.
function pastTenseProposalLabel(label){
  if(!label)return label;
  let s=label.replace(/\?$/,"");
  if(s.indexOf("Add ")===0)s="Added "+s.slice(4);
  else if(s.indexOf("Delete ")===0)s="Deleted "+s.slice(7);
  else if(s.indexOf("Move ")===0)s="Moved "+s.slice(5);
  else if(s.indexOf("Retime ")===0)s="Retimed "+s.slice(7);
  // "Set your peak focus hours to X" already reads correctly as a
  // completed action unchanged -- "set" is its own past tense.
  return s;
}
// Turns a batch of built tasks (from planBrainDumpTasks, exam branch)
// into a plain-English summary of the real spaced study-session plan --
// count/spacing plus, when the reliability engine actually changed
// where a session landed, the SAME real reason text fmtPlacementReason
// already generates elsewhere (never invented fresh for this: each
// session's own placementReason comes straight from buildExamSessionEvents/
// findReliableSlotFor). Also flags when a session lands on a day the
// digest already knows is heavier than usual -- real data, not a guess.
function describeExamSessionPlan(tasks,digest){
  const sessions=(tasks||[]).filter(t=>t.isExamPrepSession);
  if(sessions.length===0)return null;
  const lines=[sessions.length+" study session"+(sessions.length!==1?"s":"")+" scheduled between now and the exam."];
  const reasoned=sessions.filter(s=>s.placementReason).map(s=>fmtPlacementReason(s.placementReason,s.time));
  if(reasoned.length>0)lines.push(reasoned[0]);
  const heavyDates=new Set((digest&&digest.heavyDayKeys)||[]);
  const onHeavyDay=sessions.filter(s=>heavyDates.has(s.date));
  if(onHeavyDay.length>0)lines.push(onHeavyDay.length+" session"+(onHeavyDay.length!==1?"s land":" lands")+" on an already busy day -- still fits, just a heads-up.");
  return lines.join(" ");
}
// Wraps planBrainDumpTasks at single-item granularity -- the exact same
// call shape expandBrainDumpItem already proves safe and reusable.
// taskKind mirrors Brain Dump's own item kinds (study/todo/event/
// reminder/exam/project) -- unrecognized/missing defaults to "study",
// the most common "add me a task" case. Project creation always passes
// empty phases/outline -- buildAssignmentAttackBlockPair already
// degrades a phase-less project to a real marker plus an unphased
// Attack Block rather than failing (see its own comment), exactly the
// same degrade a phase-less Brain Dump project gets.
//
// An exam DOES get real spaced study sessions proposed by default now
// (proposeSessions:true) -- this was deliberately off in Phase 2
// ("that's a real, separate decision... not something to default to
// from one chat message"), reversed here on explicit request: a chat
// assistant that can only log a due date and never actually help
// prepare for it is the weak version of this feature. sessionCount is
// derived the same real way the rest of the app already does
// (defaultSessionCountFor, daysUntil-driven) rather than
// planBrainDumpTasks' own flat fallback of 4.
const STUDLIN_AI_CREATE_TASK_KINDS=new Set(["study","todo","event","reminder","exam","project"]);
function buildCreateTaskProposal(parsed,events,routines,prefs){
  const kind=STUDLIN_AI_CREATE_TASK_KINDS.has(parsed.taskKind)?parsed.taskKind:"study";
  const isExam=kind==="exam";
  let sessionCount;
  if(isExam&&parsed.dueDate){
    const daysUntil=Math.round((new Date(parsed.dueDate+"T12:00:00")-new Date(dayKey()+"T12:00:00"))/86400000);
    sessionCount=defaultSessionCountFor("major",null,daysUntil);
  }
  const item={title:parsed.title,kind,dueDate:parsed.dueDate||null,dueTime:parsed.dueTime||null,durationMin:parsed.durationMin||null,phases:[],proposeSessions:isExam,sessionCount};
  const{tasks:rawTasks,unplaced}=planBrainDumpTasks([item],events,routines,prefs);
  // Real consumer of studyStylePrefs.sessionOrder -- see
  // applySessionOrderPreference's own comment. A no-op for anyone who
  // skipped/never answered that wizard question (the common case today).
  const tasks=applySessionOrderPreference(rawTasks,prefs.studyStylePrefs&&prefs.studyStylePrefs.sessionOrder);
  if(tasks.length===0)return{ok:false,label:"Couldn't find room for \""+parsed.title+"\" -- try a different date."};
  const primary=tasks[0];
  const degraded=unplaced.some(t=>t.title===primary.title);
  let label=describeCreateProposal(primary)+(degraded?" (no open slot found -- added as a to-do instead)":"");
  if(isExam){
    const sessionSummary=describeExamSessionPlan(tasks,assembleStudlinAiDigest(events,routines,prefs,dayKey()));
    if(sessionSummary)label=label+" "+sessionSummary;
  }
  return{ok:true,kind:"create_task",tasks,label};
}
// Delete via chat. No new write logic at all -- the actual removal is
// App()'s own deleteEventFromDetail (threaded down as onDeleteEvent),
// the exact same delete-plus-5-second-Undo path every other delete
// button in this app already uses, so a chat-driven delete gets that
// same safety net for free. This function only ever RESOLVES which one
// real event is meant, it doesn't touch storage.
//
// Only ever targets a real one-off event -- a routine occurrence (a
// recurring class/habit) is deliberately never a delete candidate here:
// "delete just today's occurrence" vs "delete the whole routine" is a
// real, different decision (skip_class already has its own answer for
// the first one) that a single chat message shouldn't get to guess at.
function buildDeleteProposal(parsed,forcedId){
  const targetDate=parsed.targetDate||dayKey();
  const all=lsGet("events",[]);
  let matched;
  if(forcedId){
    matched=all.find(ev=>ev.id===forcedId)||null;
    if(!matched)return{ok:false,noMatch:true,label:"That item isn't on the calendar anymore"};
  }else{
    const{matches}=matchEventByTitle(parsed.target||"",targetDate);
    const deletable=matches.filter(m=>!m.isRoutine);
    if(deletable.length===0)return{ok:false,noMatch:true,label:"Couldn't find \""+(parsed.target||"")+"\" on "+targetDate};
    if(deletable.length>1)return{ok:false,disambiguate:deletable.map(ev=>({id:ev.id,title:ev.title,date:ev.date,time:ev.time}))};
    matched=deletable[0];
  }
  return{ok:true,kind:"delete_task",event:matched,label:"Delete \""+matched.title+"\" from "+matched.date+"?"};
}
// Declaring/changing when the student personally focuses best -- reuses
// the exact same TIER0_HOUR_BUCKETS vocabulary and setSchedulePreferences
// write pattern the existing acceptPeakHourInsight/
// acceptStrugglingBucketOffer closures already use (see App()), just
// triggered by a direct chat request instead of an accepted suggestion.
// Replaces the whole declared set with exactly this one bucket -- a
// definitive "this is when I focus best" statement, not an "also
// include this" addition (Settings' own multi-select chips still cover
// declaring more than one window).
function buildSetPeakHoursProposal(parsed,prefs){
  const bucketId=parsed.peakHours;
  const bucket=TIER0_HOUR_BUCKETS.find(b=>b.id===bucketId);
  if(!bucket)return{ok:false,label:"I couldn't tell which time of day you meant."};
  const declared=prefs.peakHourBuckets||[];
  if(declared.length===1&&declared[0]===bucketId)return{ok:false,label:"Your peak hours are already set to "+PEAK_BUCKET_LABELS[bucketId]+"."};
  // Non-blocking, same reachability warning Settings' own picker already
  // shows (see ScheduleSettingsPanel) -- still allowed, just flagged, so
  // Studlin doesn't silently pretend the declared window can be used for
  // scheduling when it falls outside the student's actual work hours.
  const winStart=timeToMinutes(prefs.workStartTime),winEnd=timeToMinutes(prefs.workEndTime);
  const unreachable=!(bucket.startMin<winEnd&&bucket.endMin>winStart);
  return{ok:true,kind:"set_peak_hours",bucketId,label:"Set your peak focus hours to "+PEAK_BUCKET_LABELS[bucketId]+"?"+(unreachable?" (heads up -- that's outside your declared work hours, so Studlin can't actually schedule around it yet)":"")};
}
// Minimum pasted-material length before a generate_study_material proposal
// is even offered -- a defense-in-depth floor underneath the classifier's
// own "only classify this way when real content was pasted" instruction
// (classifyStudlinAiMessage), same "never trust the model's own judgment
// alone for something a cheap local check can catch" reasoning the rest of
// this drawer already follows for gate checks. 200 chars is roughly a
// couple of real sentences -- short enough to allow a genuinely brief but
// real definition, long enough to reject "quiz me on chapter 3" style
// bare requests the classifier occasionally still lets through.
const STUDLIN_AI_MATERIAL_MIN_LENGTH=200;
// Same "does this text mention a real subject the student already has"
// check gatherStudlinAiCoachingContext uses for its own subject nudge --
// duplicated here (not extracted into a shared helper) since it's one
// line and the two call sites have no other overlap.
function matchSubjectInMaterialText(text){
  const subjects=getSubjects().map(s=>s.label);
  const t=(text||"").toLowerCase();
  return subjects.find(s=>s&&t.includes(s.toLowerCase()))||null;
}
// Proposal for generate_study_material -- unlike every other proposal
// builder here, the real work (an actual AI generation call) happens at
// confirm time, not here; this only decides WHETHER to offer it and what
// the card should say. materialText is the student's own raw message
// (see StudlinAiDrawer.runAction) -- the classifier is never trusted to
// echo back long pasted content itself (real risk of truncation/drift),
// so the source of truth for what gets sent to the generator is always
// the original message text, never anything the model reflected back.
function buildGenerateStudyMaterialProposal(parsed,materialText){
  const genFormat=parsed.genFormat==="quiz"?"quiz":"flashcards";
  const trimmed=(materialText||"").trim();
  if(trimmed.length<STUDLIN_AI_MATERIAL_MIN_LENGTH){
    return{ok:false,label:"Paste more of the actual material and I'll turn it into "+(genFormat==="quiz"?"a practice quiz":"flashcards")+" -- that was too short to work with."};
  }
  const subject=matchSubjectInMaterialText(trimmed);
  const label=genFormat==="quiz"
    ?"Generate a practice quiz from this"+(subject?" for "+subject:"")+"?"
    :"Generate flashcards from this"+(subject?" for "+subject:"")+"?";
  return{ok:true,kind:"generate_study_material",genFormat,materialText:trimmed,subject,label};
}
// Top-level dispatcher StudlinAiDrawer calls once a message classifies as
// an action -- normalizes all builders above into one
// {ok,kind,label,disambiguate?,noMatch?,...} shape the drawer's proposal
// card renders generically, regardless of which underlying engine ran.
// rawText is only used by generate_study_material (see above) -- every
// other intent ignores it, so a re-entry from pickDisambiguate (which
// never has it handy) is exactly as safe as before this param existed.
function buildStudlinAiActionProposal(parsed,events,routines,prefs,forcedId,rawText){
  if(parsed.intent==="create_task")return buildCreateTaskProposal(parsed,events,routines,prefs);
  if(parsed.intent==="delete_task")return buildDeleteProposal(parsed,forcedId);
  if(parsed.intent==="set_peak_hours")return buildSetPeakHoursProposal(parsed,prefs);
  if(parsed.intent==="generate_study_material")return buildGenerateStudyMaterialProposal(parsed,rawText);
  if(parsed.intent==="move_flex_task"){
    const r=buildMoveFlexTaskProposal(parsed,events,routines,prefs,forcedId);
    if(r.noMatch)return{ok:false,noMatch:true,label:r.label};
    if(r.disambiguate)return{ok:false,disambiguate:r.disambiguate,label:r.label};
    if(r.moved.length===0)return{ok:false,label:r.label};
    return{ok:true,kind:"move_flex_task",moved:r.moved,label:r.label};
  }
  const r=buildMoveFixedProposal(parsed,forcedId);
  if(r.noMatch)return{ok:false,noMatch:true,label:r.label};
  if(r.disambiguate)return{ok:false,disambiguate:r.disambiguate,label:r.label};
  if(r.moved.length===0&&r.couldntMove.length===0&&!r.skipRoutine)return{ok:false,label:"Nothing to move right now."};
  return{ok:true,kind:"move_fixed",pausePreview:r,label:r.label};
}
// Extracts what a mini visual day-preview needs from a proposal -- a
// real date + one synthetic {title,time,duration} block to render
// alongside that day's actual events -- so the drawer can show WHERE a
// proposed time lands, not just print a date string. Deliberately
// narrow: only the common single-day/single-item cases (a scheduled
// create_task, a single flexible-task move, or a single fixed-event
// move/retime) have one unambiguous day+block to show. Bulk intents
// (shift/clear_day/clear_week/skip_class, or any pausePreview moving
// more than one item) return null -- visualizing many moved items in
// one small strip isn't attempted, the existing moved/couldntMove text
// summary already covers that case reasonably.
function studlinAiProposalPreviewSpec(proposal){
  if(!proposal||!proposal.ok)return null;
  if(proposal.kind==="create_task"){
    const primary=(proposal.tasks||[])[0];
    if(!primary||!primary.time||!primary.date)return null;
    return{dateKey:primary.date,proposedBlock:{title:primary.title,time:primary.time,duration:primary.duration||30}};
  }
  if(proposal.kind==="move_flex_task"){
    const m=(proposal.moved||[])[0];
    if(!m||!m.newTime||!m.newDate)return null;
    return{dateKey:m.newDate,proposedBlock:{title:m.title,time:m.newTime,duration:m.duration||30}};
  }
  if(proposal.kind==="move_fixed"&&proposal.pausePreview&&proposal.pausePreview.moved&&proposal.pausePreview.moved.length===1){
    const m=proposal.pausePreview.moved[0];
    if(!m.newTime||!m.newDate)return null;
    return{dateKey:m.newDate,proposedBlock:{title:m.title,time:m.newTime,duration:m.newDuration||30}};
  }
  return null;
}
// A create_task exam proposal (see buildCreateTaskProposal) can carry
// several real spaced study sessions, not just the due-date marker --
// the single-day mini preview above only ever shows one day, so this
// pulls out the session dates for a horizontal timeline strip instead
// (StudlinAiMiniSessionTimeline), sorted chronologically. Returns null
// when there are no real sessions to show (a plain exam marker with no
// sessions proposed, or any other proposal kind).
function studlinAiSessionTimelineSpec(proposal){
  if(!proposal||!proposal.ok||proposal.kind!=="create_task")return null;
  const sessions=(proposal.tasks||[]).filter(t=>t.isExamPrepSession&&t.date&&t.time);
  if(sessions.length===0)return null;
  return sessions.map(s=>({date:s.date,time:s.time})).sort((a,b)=>a.date===b.date?(a.time<b.time?-1:1):(a.date<b.date?-1:1));
}
// Top-level commit helpers for the proposals above -- commitTasks and
// confirmPausePlan (both CalendarTab closures) are unreachable from
// StudlinAiDrawer, an App-level component. Rather than restructure
// either proven, already-shipped path, these replicate their exact write
// logic as plain top-level functions. Each returns the new events array;
// the caller (StudlinAiDrawer's Confirm handler) is responsible for
// lsSet-syncing it into CalendarTab's live grid via calendarSetEventsRef,
// the same bridge App()'s own event writes (deleteEventFromDetail etc.)
// already use for exactly this reason.
function commitStudlinAiTasks(tasks){
  const events=lsGet("events",[]);
  const routines=getWeeklyRoutine();
  const prefs=getSchedulePreferences();
  const datesAffected=new Set(tasks.map(t=>t.date).filter(Boolean));
  let next=events.concat(tasks);
  datesAffected.forEach(dk=>{next=rebalanceDay(dk,next,routines,prefs);});
  lsSet("events",next);
  return next;
}
// Mirrors confirmPausePlan's write body exactly (Tier 3 Reschedule) --
// kept as a separate copy rather than refactoring confirmPausePlan
// itself to call this, to keep this change's blast radius on new code
// only and not risk the already-shipped Pause flow.
function commitStudlinAiFixedMove(pausePreview){
  const all=lsGet("events",[]);
  const routineMoves=pausePreview.moved.filter(m=>m.isRoutine);
  const oneOffMoves=new Map(pausePreview.moved.filter(m=>!m.isRoutine).map(m=>[m.id,m]));
  let next=all.map(ev=>{
    if(!oneOffMoves.has(ev.id))return ev;
    const m=oneOffMoves.get(ev.id);
    return{...ev,date:m.newDate,time:m.newTime,duration:m.newDuration!=null?m.newDuration:ev.duration};
  });
  if(routineMoves.length){
    const skips=getRoutineSkips();
    const nextSkips={...skips};
    routineMoves.forEach(m=>{
      nextSkips[m.oldDate]=[...new Set([...(nextSkips[m.oldDate]||[]),m.routineId])];
      next=next.concat([{id:String(Date.now()+Math.random()*1000),title:m.title,date:m.newDate,time:m.newTime,subject:m.subject||"",kind:m.kind,notes:"",priority:null,difficulty:null,deadline:null,duration:m.newDuration||30,status:"pending",timeSpent:0,completedAt:null}]);
    });
    lsSet("routineSkips",nextSkips);
  }
  lsSet("events",next);
  if(pausePreview.skipRoutine){
    const{date,routineIds}=pausePreview.skipRoutine;
    const skips=getRoutineSkips();
    lsSet("routineSkips",{...skips,[date]:[...new Set([...(skips[date]||[]),...routineIds])]});
  }
  return next;
}
function commitStudlinAiFlexMove(moved){
  const events=lsGet("events",[]);
  const m=moved[0];
  const next=events.map(ev=>ev.id===m.id?{...ev,date:m.newDate,time:m.newTime}:ev);
  lsSet("events",next);
  return next;
}
// Same setSchedulePreferences write shape acceptPeakHourInsight/
// acceptStrugglingBucketOffer already use, for a directly-requested
// (not accepted-suggestion) peak-hours change. Not calendar data -- no
// events array to return/sync.
function commitStudlinAiPeakHours(prefs,bucketId){
  const next={...prefs,peakHourBuckets:[bucketId]};
  setSchedulePreferences(next);
  return next;
}
// Same engine as computePausePlan's shift/clear_day/clear_week tail above
// (findLegalSlotOrNull per affected event), for a different trigger: a
// student adding a holiday mid-term, over dates that may already have
// pending sessions sitting on them. The holiday itself is already saved
// by the time this preview is shown (see RoutineControlCenterModal's own
// Holidays section) -- Cancel here just leaves those sessions where they
// are, same as any holiday added today already does for everything that
// already existed; it doesn't undo the holiday. desiredDate is always the
// day right after the range (not each event's own old date) so nothing
// gets offered a slot still inside the same not-yet-persisted holiday --
// findOpenSlotFor only ever scans forward from what it's given, so the
// result can't land before that floor either.
function computeHolidayPlan(start,end,label){
  const inWindow=(ev)=>isQualifying(ev)&&ev.date>=start&&ev.date<=end;
  const afterHoliday=(()=>{const d=new Date(end+"T12:00:00");d.setDate(d.getDate()+1);return dayKey(d);})();
  const all=lsGet("events",[]);
  const routinesNow=getWeeklyRoutine();
  const prefsNow=getSchedulePreferences();
  const affected=all.filter(inWindow).sort((a,b)=>a.date===b.date?((a.time||"")<(b.time||"")?-1:1):(a.date<b.date?-1:1));
  let working=all.filter(ev=>!inWindow(ev));
  const moved=[],couldntMove=[];
  affected.forEach(ev=>{
    const slot=findLegalSlotOrNull(working,routinesNow,prefsNow,afterHoliday,ev.time||prefsNow.workStartTime,ev.duration||30,ev.deadline||null);
    if(slot){
      moved.push({id:ev.id,title:ev.title,oldDate:ev.date,oldTime:ev.time,newDate:slot.date,newTime:slot.time});
      working=working.concat([{...ev,date:slot.date,time:slot.time}]);
    }else{
      couldntMove.push({id:ev.id,title:ev.title,deadline:ev.deadline});
      working=working.concat([ev]);
    }
  });
  return {label,moved,couldntMove};
}

// Standalone wrapper around rebalanceDay for callers outside CalendarTab's
// React state (e.g. ChatDrawer, a sibling component with no access to
// CalendarTab's own commitTasks closure) — reads/writes localStorage
// directly, same idiom as scheduleAssignmentExtension and
// scheduleAttackBlockFollowUp.
function addTaskWithRebalance(task){
  const events=lsGet("events",[]);
  const next=rebalanceDay(task.date,events.concat([task]),getWeeklyRoutine(),getSchedulePreferences());
  lsSet("events",next);
  return next;
}

// Pending group-proposal calendar blocks (Schedule with Friends / Find
// Shared Study Window) carry chatRoomId+chatMessageId back to the chat
// message that's the real source of truth for who's accepted (see
// ChatDrawer's confirmStudyTime comment). This re-reads that message and
// refreshes the event's own cached proposalMemberUids/proposalResponses --
// deliberately fetch-on-demand, not a live Firestore listener: this app
// doesn't hold persistent onSnapshot listeners open for calendar data
// anywhere else (fetch-on-mount/fetch-on-action is the existing pattern,
// e.g. pullGoogleCalendarIfConnected above), and acceptance changes are
// rare and low-urgency enough that "current as of the last time you opened
// the tab or this block" is an honest, simple tradeoff, not a shortcut --
// see CLAUDE.md's "avoid overengineering." Called once on CalendarTab mount
// for every pending block, and again for a single block when its popover
// opens (see WeeklyPlanner/DayPlanner).
// Skips any event whose cached state already shows allAccepted -- once
// every invited member has accepted, computeAcceptanceSummary flips to
// allAccepted:true and the block just renders as a fully normal event from
// then on (no dim, no badge -- see the rendering in WeeklyPlanner/
// DayPlanner). There's nothing left to learn about a settled proposal, so
// it's never re-fetched again, instead of paying for that request forever.
// ids (optional): restrict the refresh to specific event ids (a single
// block's popover opening); omitted, it refreshes every still-pending
// proposal on the calendar (CalendarTab's mount effect).
// Returns the updated events array (and persists it), or null if nothing
// needed refreshing / nothing actually changed -- callers should only call
// setEvents when they get a real array back.
async function refreshPendingAcceptance(events,ids){
  const targets=(events||[]).filter(ev=>ev.chatRoomId&&ev.chatMessageId&&ev.proposalMemberUids
    &&!computeAcceptanceSummary(ev.proposalMemberUids,ev.proposalResponses).allAccepted
    &&(!ids||ids.includes(ev.id)));
  if(targets.length===0)return null;
  const fetched=await Promise.all(targets.map(ev=>
    fsdb().collection('chatRooms').doc(ev.chatRoomId).collection('messages').doc(ev.chatMessageId).get()
      .then(doc=>doc.exists?{id:ev.id,memberUids:doc.data().memberUids||ev.proposalMemberUids,responses:doc.data().responses||{}}:null)
      .catch(()=>null)
  ));
  let changed=false;
  const next=events.map(ev=>{
    const u=fetched.find(x=>x&&x.id===ev.id);
    if(!u)return ev;
    changed=true;
    return {...ev,proposalMemberUids:u.memberUids,proposalResponses:u.responses};
  });
  if(!changed)return null;
  lsSet("events",next);
  return next;
}

// Feature 3: Task priority scoring (0-1000 scale with exponential deadline urgency)
function calculateTaskPriority(task,allTasks){
  let score=0;
  const prefs=getSchedulePreferences();
  const now=new Date();
  
  // Base priority (user-set) -- normalizeTaskVal handles the two live
  // scales (legacy raw 0-10 vs. the current 0-1000 slider) the same way
  // scoreTask already does; a raw read here meant every slider-created
  // task (priority commonly ~500) silently tied at the max score below,
  // and the difficulty branch's raw >=3/<=2 checks similarly misfired for
  // almost any slider value.
  const basePriority=normalizeTaskVal(task.priority,3)*10;
  score+=basePriority*100;
  
  // Deadline urgency (exponential scaling as due date approaches)
  if(task.deadline){
    const dueDate=new Date(task.deadline);
    const hoursDue=(dueDate-now)/(1000*60*60);
    if(hoursDue<=0){
      score+=300;
    }else if(hoursDue<=6){
      score+=250;
    }else if(hoursDue<=24){
      score+=200;
    }else if(hoursDue<=72){
      score+=120;
    }else{
      score+=Math.max(0,100-hoursDue/24);
    }
  }
  
  // Difficulty preference weighting
  const diff=normalizeTaskVal(task.difficulty,2)*10;
  if(prefs.difficultyPreference==="hardFirst"&&diff>=3){
    score+=150;
  }else if(prefs.difficultyPreference==="easyFirst"&&diff<=2){
    score+=100;
  }
  
  // Duration penalty (longer tasks score lower to prioritize quick wins)
  const dur=task.duration||30;
  if(dur>90)score-=50;
  else if(dur>60)score-=25;
  
  return Math.min(1000,Math.max(0,score));
}

// Feature 4: Duration-aware chunking & auto-inject breaks -- splits a task
// longer than 90min into 45-min chunks + 15-min breaks, purely for Today's
// Plan's display. Only ever called on tasks that already have a real,
// committed `.time` (either a real calendar event's own time, or a slot
// Today's Plan itself just found for a genuinely timeless item) -- there's
// no anchor to chunk from otherwise, and this never changes what's
// actually on the calendar, only how one long sitting is broken up on
// screen.
function chunkTasksWithBreaks(tasks){
  const chunked=[];
  tasks.forEach(task=>{
    if((task.duration||0)<=90||!task.time){
      chunked.push(task);
      return;
    }
    const dur=task.duration;
    let chunks=Math.ceil(dur/45);
    // Avoid a near-empty trailing chunk (e.g. 91min -> 45/45/1, a study
    // block shorter than the 15-min break placed right before it) -- fold
    // the remainder into the last chunk instead of spawning a tiny extra
    // one when it'd be under a 20-min floor.
    if(chunks>1&&dur-((chunks-1)*45)<20)chunks-=1;
    let cursorMins=timeToMinutes(task.time);
    for(let i=0;i<chunks;i++){
      const chunkDur=i<chunks-1?45:dur-(45*(chunks-1));
      chunked.push({
        ...task,
        // Only the first chunk keeps the real event id -- Today's Plan's
        // checkbox and Reschedule button both key off a real events[] id
        // matching, and later chunks/breaks are display-only continuations
        // of the same real session, never independently actionable (see
        // Dashboard's row render, which gates on chunkIndex).
        id:i===0?task.id:task.id+"-chunk-"+i,
        title:task.title+(chunks>1?` (Part ${i+1}/${chunks})`:""),
        time:minutesToTime(cursorMins),
        duration:chunkDur,
        // The real session's own full duration, separate from this one
        // chunk's 45-min slice -- Reschedule (only ever offered on chunk 0)
        // needs to search for room for the WHOLE session, not just its
        // first piece, or it could suggest a day that only actually has
        // room for 45 minutes of it.
        fullDuration:dur,
        parentId:task.id,
        isChunk:true,
        chunkIndex:i,
      });
      cursorMins+=chunkDur;
      if(i<chunks-1){
        chunked.push({
          id:"break-"+task.id+"-"+i,
          title:"Break",
          time:minutesToTime(cursorMins),
          duration:15,
          isBreak:true,
          subject:"Rest",
          priority:1,
          status:task.status,
        });
        cursorMins+=15;
      }
    }
  });
  return chunked;
}

// Feature 5: Conflict detection (detect overlaps with hard events)
// Checks a proposed [startMins, startMins+duration) window against a list of
// already-occupied {start,end} slots. (This used to check `.time`/`.id`/
// `.isFlexible` on entries that never had those fields — always `false`,
// i.e. conflict detection was silently inert. Now it actually does interval
// overlap math against the shape callers actually pass.)
function detectConflicts(task,occupiedSlots,startMins){
  const taskDur=task.duration||30;
  const taskEnd=startMins+taskDur;
  return occupiedSlots.some(slot=>!(taskEnd<=slot.start||startMins>=slot.end));
}

// Feature 2+Features 1,3,4,5: Integrated advanced scheduler
function advancedSchedulePlanner(baseEvents){
  const prefs=getSchedulePreferences();
  const tk=dayKey();

  // Get all events for today — checklist to-dos are excluded, they have no
  // duration and never belong in the scheduled day plan.
  const events=baseEvents.filter(e=>e.date===tk&&!e.checklist);
  const now=new Date();
  const nowMins=timeToMinutes(String(now.getHours()).padStart(2,"0")+":"+String(now.getMinutes()).padStart(2,"0"));
  // Floor for placing anything today: now + 15min buffer, rounded up to the
  // 15-min grid this planner already steps on. Without this, flexible tasks
  // with no time yet always landed at workStartTime regardless of the clock.
  const nowFloorMins=Math.ceil((nowMins+15)/15)*15;

  // Time window constraints
  const todayWindow=getWorkWindowMinsFor(prefs,tk);
  const workStart=Math.max(todayWindow.start,nowFloorMins);
  const workEnd=todayWindow.end;

  // Separate hard (fixed/pinned/done, never reordered) from flexible --
  // isReorderableTask is the exact same predicate rebalanceDay uses for the
  // real calendar, so Today's Plan can never disagree with an actual
  // reshuffle about what counts as flexible.
  const hardEvents=events.filter(e=>e.time&&!isReorderableTask(e));
  // A flexible task that already has a real committed time (an Attack
  // Block session, exam-prep session, manual/AI-arranged block) keeps that
  // exact time -- this never runs it back through the slot scanner, so
  // Today's Plan can never show a different time than the real Calendar
  // for the same event. Only a genuinely timeless due-today item (nothing
  // scheduled for it yet) goes through the scan below, and only those
  // compete against each other on priority for the scarce slots it finds.
  const flexibleTimed=events.filter(e=>e.time&&isReorderableTask(e));
  const flexibleTimeless=events.filter(e=>!e.time&&isReorderableTask(e))
    .sort((a,b)=>calculateTaskPriority(b,events)-calculateTaskPriority(a,events));

  // Weekly Routine occurrences for today are absolute shields, folded into
  // occupiedSlots right alongside real hard events. "Free period" occurrences
  // are tracked separately as preferred landing spots for short micro-tasks.
  const routineToday=getRoutineOccurrencesForDate(tk);
  const shieldOccurrences=routineToday.filter(r=>r.kind!=="free period");
  const freeWindows=routineToday.filter(r=>r.kind==="free period").map(r=>({start:timeToMinutes(r.time),end:timeToMinutes(r.time)+(r.duration||30)}));

  // Seeded with everything that already has a real, fixed span -- hard
  // events AND already-timed flexible tasks both have to block a timeless
  // item from landing on top of them. 2026-08-25 regression: only the
  // trailing side (effectiveTrailOut) was ever applied here -- the leading
  // buffer (effectiveLeadIn, e.g. a commute time set before a fixed event)
  // was silently dropped, and shieldOccurrences (today's classes) got
  // neither side at all -- so a timeless task could land right up against
  // the start of a class/commute with zero gap. Now matches the same
  // effectiveLeadIn/effectiveTrailOut treatment every other occupied-
  // interval builder in this file already uses.
  // !e.timeUnconfirmed (2026-08-26) -- excluded from the OCCUPIED-slot math
  // only, not from hardEvents/flexibleTimed themselves (those still drive
  // the visible plan list -- an exam still shows as due today, it just
  // never blocks a real timeless task from landing near its fake time).
  // e.status!=="done" (2026-08-26) -- hardEvents is !isReorderableTask,
  // which is true for a done task same as a fixed one (see
  // isReorderableTask), so a finished task was still ending up in here and
  // blocking new placements at a slot that's actually free now. Same
  // surgical scope as timeUnconfirmed above: still shows on the plan list
  // as completed, just stops occupying real time.
  const occupiedSlots=[
    ...hardEvents.filter(e=>!e.timeUnconfirmed&&e.status!=="done").map(e=>({start:timeToMinutes(e.time)-effectiveLeadIn(e),end:timeToMinutes(e.time)+(e.duration||30)+effectiveTrailOut(e)})),
    ...flexibleTimed.filter(e=>!e.timeUnconfirmed).map(e=>({start:timeToMinutes(e.time)-effectiveLeadIn(e),end:timeToMinutes(e.time)+(e.duration||30)+effectiveTrailOut(e)})),
    ...shieldOccurrences.map(r=>({start:timeToMinutes(r.time)-effectiveLeadIn(r),end:timeToMinutes(r.time)+(r.duration||30)+effectiveTrailOut(r)})),
  ];

  // Place genuinely timeless flexible tasks into whatever room is left,
  // highest-priority first.
  const placedTimeless=[];
  const unplacedTimeless=[];
  flexibleTimeless.forEach(task=>{
    const dur=task.duration||30;
    let placed=false;

    // Short tasks (flashcards/quick review, ≤20 min) preferentially land
    // inside a free-period/study-hall window before using the general peak
    // window — that's the "Dead Time Activation" the free periods exist for.
    if(dur<=20){
      for(const w of freeWindows){
        const wStart=Math.max(w.start,nowFloorMins);
        for(let timeSlot=wStart;timeSlot+dur<=w.end&&!placed;timeSlot+=15){
          if(!detectConflicts(task,occupiedSlots,timeSlot)){
            occupiedSlots.push({start:timeSlot,end:timeSlot+dur});
            placedTimeless.push({...task,time:minutesToTime(timeSlot)});
            placed=true;
          }
        }
        if(placed)break;
      }
    }

    // Try to find first available slot within work window
    if(!placed){
      for(let timeSlot=workStart;timeSlot+dur<=workEnd;timeSlot+=15){
        if(!detectConflicts(task,occupiedSlots,timeSlot)){
          occupiedSlots.push({start:timeSlot,end:timeSlot+dur});
          placedTimeless.push({...task,time:minutesToTime(timeSlot)});
          placed=true;
          break;
        }
      }
    }

    if(!placed){
      unplacedTimeless.push({...task,reason:"No available window within preferred hours"});
    }
  });

  // Every task with a real placement time -- hard events untouched, real
  // flexible sessions at their own committed time, timeless ones at
  // whatever slot was just found -- is eligible for chunking: a long
  // single sitting gets split into 45-min pieces with breaks purely for
  // display, never touching the real calendar event or its committed time.
  const chunked=chunkTasksWithBreaks([...flexibleTimed,...placedTimeless]);

  // Merge everything and sort by actual start time. Previously hard events
  // were pushed first and flexible ones appended after with no real sort --
  // that only ever looked right because the flexible bucket was always
  // empty (isFlexible was never set anywhere). Anything with no time (a
  // task that genuinely couldn't be placed anywhere today) sorts last.
  // shieldOccurrences (today's classes/activities) were already computed
  // above and used to block flexible tasks from landing on top of them --
  // but never actually shown here, so "Today's plan" silently omitted
  // every class while still correctly working around them. Included now
  // so the plan reads as an honest full picture of the day, not just the
  // to-do portion of it.
  return [...hardEvents,...chunked,...unplacedTimeless,...shieldOccurrences]
    .map(t=>({...t,done:t.status==="done",scheduled:!!t.time}))
    .sort((a,b)=>{
      if(!a.time&&!b.time)return 0;
      if(!a.time)return 1;
      if(!b.time)return -1;
      return a.time<b.time?-1:a.time>b.time?1:0;
    });
}

function todaysPlan(){
  const events=lsGet("events",[]);
  return advancedSchedulePlanner(events);
}

// rearrangeUserTasks (a duplicate, raw-scale-priority version of
// calculateTaskPriority/advancedSchedulePlanner below) was removed here --
// confirmed zero callers anywhere in the file.


// Standalone versions of CalendarTab's own markDone/uncrossDone (which stay
// as thin wrappers around these, so its own callers are unaffected) --
// pulled out so Dashboard's Today's Plan checkbox can complete a task the
// exact same way Calendar's own click-to-toggle does, both writing the
// real ev.status everyone else already reads (Calendar's grid, Tier 0, XP/
// streak tracking). This replaces the old togglePlanDone/"planDone" shadow
// map, which only ever toggled a side localStorage key Dashboard alone
// read -- checking something off in Today's Plan never touched the real
// event, so Calendar (and everything else keyed off ev.status) still saw
// it as pending. planDone is fully retired, not just unused: its own two
// read sites (here and Dashboard's checkbox) are both gone now.
function markEventDone(id){
  const events=lsGet("events",[]);
  const target=events.find(ev=>ev.id===id);
  if(target&&target.time)logCompletionOutcome("done",target.time,difficultyTierOf(target),target.id,target.subject);
  const next=events.map(ev=>{if(ev.id!==id)return ev;const {movedByStudlin,movedFrom,movedAt,...rest}=ev;return {...rest,status:"done",completedAt:Date.now()};});
  lsSet("events",next);
  return next;
}
function uncrossEventDone(id){
  const events=lsGet("events",[]);
  const next=events.map(ev=>ev.id===id?{...ev,status:"pending"}:ev);
  lsSet("events",next);
  return next;
}
function profileStats(){const s=lsGet("sessions",[]);const totalMin=s.reduce((a,x)=>a+(x.m||0),0);const st=sessionStats();return {totalMin,focusSessions:s.length,weekMin:st.weekMin,avg:st.avg};}
// No more manual Time Zone picker in Settings — always the browser's actual
// current zone, computed fresh rather than trusted from a possibly-stale
// stored value (e.g. a profile saved before a student traveled/moved).
function detectTz(){
  try{return Intl.DateTimeFormat().resolvedOptions().timeZone||"America/New_York";}catch(e){return "America/New_York";}
}
function getProfile(){
  try{
    const u=typeof firebase!=="undefined"?firebase.auth().currentUser:null;
    const def={name:(u&&u.displayName)||"Student",email:(u&&u.email)||"you@studlin.app",school:"",tz:detectTz(),status:"",affiliation:""};
    return {...lsGet("profile",def),tz:detectTz()};
  }catch(e){return{name:"Student",email:"you@studlin.app",school:"",tz:detectTz(),status:"",affiliation:""};}
}
function getUserPicUrl(){return lsGet("profilePic","");}
function getUserInitials(){
  try{
    const u=typeof firebase!=="undefined"?firebase.auth().currentUser:null;
    const n=(u&&u.displayName)||getProfile().name||"S";
    if(!n)return "S";
    const p=n.trim().split(" ").filter(Boolean);
    return p.length>1?(p[0][0]+p[p.length-1][0]).toUpperCase():n.slice(0,2).toUpperCase();
  }catch(e){return "S";}
}
function getUserName(){
  try{
    const u=typeof firebase!=="undefined"?firebase.auth().currentUser:null;
    return (u&&u.displayName)||getProfile().name||"Student";
  }catch(e){return "Student";}
}
function saveProfile(p){lsSet("profile",p);}
function seedEventsIfStale(){
  return;
  const ev=lsGet("events",null); const tk=dayKey();
  if(ev&&ev.some(e=>e.date>=tk))return;
  const mk=(off,time,title,subject,kind)=>{const d=new Date();d.setDate(d.getDate()+off);return {id:"seed-"+off+"-"+time,date:dayKey(d),time,title,subject,kind};};
  lsSet("events",[
    mk(0,"14:30","Chem quiz · Periodic trends","Chemistry","exam"),
    mk(0,"19:00","Macbeth essay · draft a section","English IV","study block"),
    mk(0,"21:00","Bio · cell respiration review","Biology","study block"),
    mk(1,"23:59","Biology lab report due","Biology","deadline"),
    mk(3,"09:00","Macbeth essay · first draft","English IV","deadline"),
    mk(5,"10:00","Calculus test · Derivatives","Calculus","exam"),
  ]);
}

// ─── SCHEDULE SETTINGS PANEL (Feature 2: Editable Preferences) ─────────────────
function ScheduleSettingsPanel({open,onClose,onSave}){
  const prefs=getSchedulePreferences();
  const [workStart,setWorkStart]=useState(prefs.workStartTime);
  const [workEnd,setWorkEnd]=useState(prefs.workEndTime);
  const [difficulty,setDifficulty]=useState(prefs.difficultyPreference);
  const [weekendEnabled,setWeekendEnabled]=useState(prefs.weekendEnabled);
  const [weekendStart,setWeekendStart]=useState(prefs.weekendStartTime);
  const [weekendEnd,setWeekendEnd]=useState(prefs.weekendEndTime);
  const [peakBuckets,setPeakBuckets]=useState(prefs.peakHourBuckets||[]);
  const [manualBufferMode,setManualBufferMode]=useState(prefs.manualBufferMode||"off");
  const [automatedBufferEnabled,setAutomatedBufferEnabled]=useState(prefs.automatedBufferEnabled!==false);
  const togglePeakBucket=(id)=>setPeakBuckets(peakBuckets.includes(id)?peakBuckets.filter(b=>b!==id):[...peakBuckets,id]);
  const [saved,setSaved]=useState(false);

  // An end time at or before start time leaves the scheduler with a
  // zero-width or inverted window it can never actually place anything
  // in — findOpenSlotFor/findFixedEventSlot don't error on that, they
  // silently fall back to handing back whatever slot was asked for,
  // unchecked. Catching it here, before it's ever saved, is simpler and
  // safer than trying to make every downstream scheduling function defend
  // against a schedule that was never valid to begin with.
  const workHoursInvalid=timeToMinutes(workEnd)<=timeToMinutes(workStart);
  const weekendHoursInvalid=weekendEnabled&&timeToMinutes(weekendEnd)<=timeToMinutes(weekendStart);
  const canSave=!workHoursInvalid&&!weekendHoursInvalid;

  // A declared peak bucket only ever actually influences placement (see
  // findTier0Slot/findReliableSlotFor) when it overlaps the student's own
  // work-hours window at all — "Morning" (6-11am) or "Evening" (6-10pm)
  // against this app's own default 9am-6pm window has zero overlap, so
  // picking either did nothing and said nothing about why. Purely
  // informational (never blocks Save) — the student may genuinely want to
  // declare a preference now and widen their hours to match later.
  const unreachablePeakBuckets=!workHoursInvalid?TIER0_HOUR_BUCKETS.filter(b=>
    peakBuckets.includes(b.id)&&!(b.startMin<timeToMinutes(workEnd)&&b.endMin>timeToMinutes(workStart))
  ):[];

  // Gap fix: Work Hours vs. the student's actual weekly class schedule
  // could conflict with no warning at all -- if class meeting times
  // swallow nearly all of a declared Work Hours window on some weekday,
  // findOpenSlotFor effectively has nowhere left to place anything that
  // day (and, in the worst case, could fall through to its own unguarded
  // last-resort fallback -- see findOpenSlotFor's own comment). Flags a
  // weekday where class time covers 90%+ of the Work Hours window. Purely
  // informational, matches the peak-bucket warning above (never blocks
  // Save) -- a real conflict is still a legitimate situation (Work Hours
  // is meant to be the AFTER-school study window for a day school
  // already occupies most of), this only makes sure the student can see
  // it rather than wondering why nothing gets scheduled some days.
  const DAY_NAMES_FULL=["Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"];
  const classHeavyDays=!workHoursInvalid?(()=>{
    const winStart=timeToMinutes(workStart),winEnd=timeToMinutes(workEnd);
    const winSize=winEnd-winStart;
    if(winSize<=0)return [];
    const routines=getWeeklyRoutine();
    return [0,1,2,3,4,5,6].filter(dow=>{
      const occupied=routines.filter(r=>r.kind==="class"&&Array.isArray(r.days)&&r.days.includes(dow)).reduce((sum,r)=>{
        const s=timeToMinutes(r.startTime),e=s+(r.duration||0);
        const overlap=Math.min(e,winEnd)-Math.max(s,winStart);
        return sum+Math.max(0,overlap);
      },0);
      return occupied>=winSize*0.9;
    }).map(dow=>DAY_NAMES_FULL[dow]);
  })():[];

  const handleSave=()=>{
    if(!canSave)return;
    const newPrefs={
      ...prefs,
      workStartTime:workStart,
      workEndTime:workEnd,
      difficultyPreference:difficulty,
      weekendEnabled,
      weekendStartTime:weekendStart,
      weekendEndTime:weekendEnd,
      peakHourBuckets:peakBuckets,
      manualBufferMode,
      automatedBufferEnabled,
    };
    setSchedulePreferences(newPrefs);
    setSaved(true);
    setTimeout(()=>setSaved(false),2000);
    if(onSave)onSave();
  };
  
  if(!open)return null;
  
  return (
    <div onClick={onClose} style={{position:"fixed",inset:0,zIndex:95,background:"rgba(8,12,10,0.72)",backdropFilter:"blur(7px)",display:"flex",alignItems:"center",justifyContent:"center",padding:16}}>
      <div onClick={e=>e.stopPropagation()} style={{width:520,maxWidth:"100%",background:T.card,border:"1px solid "+T.border,borderRadius:8,padding:26,boxShadow:"0 40px 90px -30px rgba(0,0,0,0.65)",maxHeight:"90vh",overflowY:"auto"}}>
        <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:24}}>
          <span style={{display:"inline-flex",width:34,height:34,borderRadius:10,background:T.lime+"20",border:"1px solid "+T.lime+"44",alignItems:"center",justifyContent:"center",color:T.lime}}>{Icon.settings}</span>
          <div style={{fontSize:18,fontWeight:700,color:T.white,letterSpacing:"-0.01em"}}>Study Schedule Preferences</div>
        </div>
        
        <div style={{marginBottom:22}}>
          <label style={{display:"block",fontSize:11,fontWeight:700,letterSpacing:"0.08em",textTransform:"uppercase",color:T.muted,marginBottom:8}}>Work Hours</label>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12}}>
            <div>
              <label style={{fontSize:12,color:T.text,marginBottom:4,display:"block"}}>Start time</label>
              <TimeInput value={workStart} onChange={setWorkStart} style={{fontFamily:T.mono}} />
            </div>
            <div>
              <label style={{fontSize:12,color:T.text,marginBottom:4,display:"block"}}>End time</label>
              <TimeInput value={workEnd} onChange={setWorkEnd} style={{fontFamily:T.mono}} />
            </div>
          </div>
          {workHoursInvalid
            ?<div style={{fontSize:11.5,color:T.red,marginTop:6}}>End time must be after start time.</div>
            :<div style={{fontSize:11,color:T.muted,marginTop:6,lineHeight:1.4}}>Tasks will be scheduled within this window. Your study schedule respects these hours.</div>}
          {classHeavyDays.length>0&&(
            <div style={{fontSize:11.5,color:T.amber,marginTop:8,lineHeight:1.4}}>
              Your classes take up almost all of this window on {classHeavyDays.join(", ")} — Studlin will have little to no room to schedule anything those days. If Work Hours is meant to be your after-school study time, consider narrowing it to when class actually lets out.
            </div>
          )}
        </div>

        <div style={{marginBottom:22}}>
          <div onClick={()=>setWeekendEnabled(!weekendEnabled)} style={{display:"flex",alignItems:"center",justifyContent:"space-between",cursor:"pointer",marginBottom:weekendEnabled?12:0}}>
            <label style={{fontSize:11,fontWeight:700,letterSpacing:"0.08em",textTransform:"uppercase",color:T.muted,cursor:"pointer"}}>Different Weekend Hours</label>
            <div style={{width:34,height:19,borderRadius:99,background:weekendEnabled?T.lime:T.card2,border:"1px solid "+(weekendEnabled?T.lime:T.border),position:"relative",transition:"all 0.15s",flexShrink:0}}>
              <div style={{position:"absolute",top:1,left:weekendEnabled?16:1,width:15,height:15,borderRadius:"50%",background:weekendEnabled?T.ink:T.muted,transition:"all 0.15s"}}/>
            </div>
          </div>
          {weekendEnabled&&(
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12}}>
              <div>
                <label style={{fontSize:12,color:T.text,marginBottom:4,display:"block"}}>Sat/Sun start</label>
                <TimeInput value={weekendStart} onChange={setWeekendStart} style={{fontFamily:T.mono}} />
              </div>
              <div>
                <label style={{fontSize:12,color:T.text,marginBottom:4,display:"block"}}>Sat/Sun end</label>
                <TimeInput value={weekendEnd} onChange={setWeekendEnd} style={{fontFamily:T.mono}} />
              </div>
            </div>
          )}
          {weekendHoursInvalid
            ?<div style={{fontSize:11.5,color:T.red,marginTop:6}}>End time must be after start time.</div>
            :<div style={{fontSize:11,color:T.muted,marginTop:6,lineHeight:1.4}}>{weekendEnabled?"Weekends will use this window instead of your weekday hours.":"Off — weekends use the same hours as weekdays."}</div>}
        </div>

        {/* 2026-08-26: manual placement (drag/drop, a hand-typed Add Task
            time) used to always guess a cushion next to a class -- a flat
            15-min "arrive early" before it, plus a proportional 5-20min
            "breathing room" after it -- even though neither is a real fact
            you declared, just Studlin's own guess. Off by default now:
            only a real literal time overlap or real commute time you
            typed in blocks a manual placement. "Short"/"Medium"/"Long"
            restore that guessed cushion at three different strengths for
            a student who wants some breathing room back -- "Medium" is
            the exact original formula, unchanged. This only ever governs
            YOUR OWN deliberate placements -- automated scheduling has its
            own separate toggle just below. */}
        <div style={{marginBottom:22}}>
          <label style={{display:"block",fontSize:11,fontWeight:700,letterSpacing:"0.08em",textTransform:"uppercase",color:T.muted,marginBottom:8}}>Buffer On Your Own Placements</label>
          <div style={{display:"flex",gap:8}}>
            {[
              {value:"off",label:"Off",desc:"Only real overlap/commute blocks it"},
              {value:"short",label:"Short",desc:"A light, flat few-minute cushion"},
              {value:"medium",label:"Medium",desc:"Studlin's original guessed cushion"},
              {value:"long",label:"Long",desc:"A noticeably wider transition gap"},
            ].map(opt=>(
              <button
                key={opt.value}
                onClick={()=>setManualBufferMode(opt.value)}
                style={{
                  flex:1,padding:12,borderRadius:8,border:"1px solid "+(manualBufferMode===opt.value?T.lime+"66":T.border),
                  background:manualBufferMode===opt.value?T.lime+"14":"transparent",
                  color:manualBufferMode===opt.value?T.lime:T.muted,
                  fontSize:12,fontWeight:manualBufferMode===opt.value?600:500,
                  cursor:"pointer",
                  transition:"all 0.15s",
                  textAlign:"left",
                }}
              >
                <div style={{fontWeight:600}}>{opt.label}</div>
                <div style={{fontSize:10.5,opacity:0.8,marginTop:2}}>{opt.desc}</div>
              </button>
            ))}
          </div>
        </div>

        {/* Separate from the mode picker above on purpose -- this governs
            Studlin's OWN automated scheduling (Today's Plan, Brain Dump,
            AI-arranged sessions), not anything you place yourself.
            Defaults on: an algorithm placing dozens of blocks a week has
            no eyes of its own to notice a schedule packed second-to-
            second, unlike a student placing one task manually who can see
            that for themselves. Turning this off means Studlin may pack
            automated placements right up against a class's real end time,
            with no cushion beyond real declared commute. */}
        <div style={{marginBottom:22}}>
          <div onClick={()=>setAutomatedBufferEnabled(!automatedBufferEnabled)} style={{display:"flex",alignItems:"center",justifyContent:"space-between",cursor:"pointer"}}>
            <label style={{fontSize:11,fontWeight:700,letterSpacing:"0.08em",textTransform:"uppercase",color:T.muted,cursor:"pointer"}}>Buffer On Automatic Scheduling</label>
            <div style={{width:34,height:19,borderRadius:99,background:automatedBufferEnabled?T.lime:T.card2,border:"1px solid "+(automatedBufferEnabled?T.lime:T.border),position:"relative",transition:"all 0.15s",flexShrink:0}}>
              <div style={{position:"absolute",top:1,left:automatedBufferEnabled?16:1,width:15,height:15,borderRadius:"50%",background:automatedBufferEnabled?T.ink:T.muted,transition:"all 0.15s"}}/>
            </div>
          </div>
          <div style={{fontSize:11,color:T.muted,marginTop:6,lineHeight:1.4}}>{automatedBufferEnabled?"On — when Studlin places something for you (Today's Plan, Brain Dump, AI-scheduled sessions), it still leaves a guessed transition cushion next to your classes.":"Off — Studlin may pack automated placements right up against a class's real end time, with only real commute time (not a guess) as a cushion."}</div>
        </div>

        <div style={{marginBottom:22}}>
          <label style={{display:"block",fontSize:11,fontWeight:700,letterSpacing:"0.08em",textTransform:"uppercase",color:T.muted,marginBottom:8}}>Difficulty Preference</label>
          <div style={{display:"flex",gap:8}}>
            {[
              {value:"easyFirst",label:"Easy First",desc:"Tackle quick wins before hard tasks"},
              {value:"balanced",label:"Balanced",desc:"Mix easy and hard throughout"},
              {value:"hardFirst",label:"Hard First",desc:"Hit hard tasks during peak focus"},
            ].map(opt=>(
              <button
                key={opt.value}
                onClick={()=>setDifficulty(opt.value)}
                style={{
                  flex:1,padding:12,borderRadius:8,border:"1px solid "+(difficulty===opt.value?T.lime+"66":T.border),
                  background:difficulty===opt.value?T.lime+"14":"transparent",
                  color:difficulty===opt.value?T.lime:T.muted,
                  fontSize:12,fontWeight:difficulty===opt.value?600:500,
                  cursor:"pointer",
                  transition:"all 0.15s",
                  textAlign:"left",
                }}
              >
                <div style={{fontWeight:600}}>{opt.label}</div>
                <div style={{fontSize:10.5,opacity:0.8,marginTop:2}}>{opt.desc}</div>
              </button>
            ))}
          </div>
        </div>

        <div style={{marginBottom:22}}>
          <label style={{display:"block",fontSize:11,fontWeight:700,letterSpacing:"0.08em",textTransform:"uppercase",color:T.muted,marginBottom:8}}>
            Peak Focus Hours <span style={{textTransform:"none",fontWeight:400,color:T.faint}}>(optional)</span>
          </label>
          <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
            {TIER0_HOUR_BUCKETS.map(b=>(
              <button key={b.id} type="button" onClick={()=>togglePeakBucket(b.id)} style={peakChipStyle(peakBuckets.includes(b.id))}>
                {PEAK_BUCKET_LABELS[b.id]}
                <span style={{opacity:0.7,marginLeft:4}}>{fmtClock12(minutesToTime(b.startMin))}–{fmtClock12(minutesToTime(b.endMin))}</span>
              </button>
            ))}
          </div>
          <div style={{fontSize:11,color:T.muted,marginTop:6,lineHeight:1.4}}>Studlin prefers these times when rescheduling missed tasks. Pick 1-2 for the strongest effect. Leave blank and Studlin will learn your best hours from your habits over time.</div>
          {unreachablePeakBuckets.length>0&&(
            <div style={{fontSize:11.5,color:T.amber,marginTop:8,lineHeight:1.4}}>
              {unreachablePeakBuckets.map(b=>PEAK_BUCKET_LABELS[b.id]).join(" and ")} {unreachablePeakBuckets.length>1?"don't":"doesn't"} overlap your Work Hours ({fmtClock12(workStart)}–{fmtClock12(workEnd)}) at all, so Studlin can't actually place anything there yet — widen your Work Hours above to cover it.
            </div>
          )}
        </div>

        {saved&&<div style={{background:T.lime+"20",border:"1px solid "+T.lime+"44",borderRadius:8,padding:12,fontSize:12,color:T.lime,marginBottom:16,display:"flex",alignItems:"center",gap:8}}>
          <span style={{display:"inline-flex"}}>✓</span>
          Preferences saved! Your schedule will instantly re-sort.
        </div>}
        
        <div style={{display:"flex",gap:10,justifyContent:"flex-end"}}>
          <button onClick={onClose} style={{padding:"10px 18px",borderRadius:8,border:"1px solid "+T.border,background:"transparent",color:T.muted,fontSize:12.5,fontWeight:600,cursor:"pointer",fontFamily:T.font}}>Cancel</button>
          <button onClick={handleSave} disabled={!canSave} style={{padding:"10px 18px",borderRadius:8,border:"none",background:T.lime,color:T.ink,fontSize:12.5,fontWeight:600,cursor:canSave?"pointer":"not-allowed",fontFamily:T.font,opacity:canSave?1:0.45}}>Save Preferences</button>
        </div>
      </div>
    </div>
  );
}

