  // silently lost).
  const queueInsightNudge=(kind,payload)=>{
    lsSet("queuedInsightNudges",[...lsGet("queuedInsightNudges",[]),{kind,payload,queuedAt:Date.now()}]);
  };
  // The other half of the fix above: pulls whatever queued up while
