  // once recovery is actually resolved (see the rebuild-confirm handler
  // below, where setCatchUpBanner(null) fires).
  const drainQueuedInsightNudges=()=>{
    const queued=lsGet("queuedInsightNudges",[]);
    if(queued.length===0)return;
    const latest=pickLatestQueuedNudgesByKind(queued);
    if(latest.strugglingBucket)setStrugglingBucketOffer(latest.strugglingBucket);
    if(latest.peakInsight)setPeakInsightOffer(latest.peakInsight);
    if(latest.examPrep)setExamPrepSuggestion(latest.examPrep);
    if(latest.prepPromptBatch)setPrepPromptBatch(latest.prepPromptBatch);
    lsSet("queuedInsightNudges",[]);
  };
  // taskOverride: the diagnostic-quiz flow passes the just-completed task
  // directly and owns its own diagnosticQuiz modal state instead (skips
  // setExamCheckIn(null) below) -- every existing caller omits it and
  // keeps reading/clearing examCheckIn exactly as before.
  const submitExamCheckIn=(rating,taskOverride)=>{
    const ci=taskOverride||examCheckIn;
    if(!ci)return;
    // Always upgrades this session's own completionLog row with the
    // rating (see applyCheckInRating) so the scheduling-reliability signal
    // reflects how it actually went, not just that it got marked done —
    // this part applies to every flexible study block, exam-linked or not.
    applyCheckInRating(ci.id,rating);
    const events=lsGet("events",[]);
    const examEvent=ci.dueEventId?events.find(e=>e.id===ci.dueEventId):null;
    if(!taskOverride)setExamCheckIn(null);
    // Everything below here is exam-prep-specific pacing (shorten/drop/
    // pull-closer remaining sessions) — a plain (non-exam-linked) study
    // block has nothing to pace, so it stops here.
    if(!examEvent)return;
    const updatedExam={...examEvent,confidenceLog:[...(examEvent.confidenceLog||[]),rating]};
    const nextEvents=events.map(e=>e.id===examEvent.id?updatedExam:e);
    lsSet("events",nextEvents);
    // The scenario this is for: session 1 just finished and the student
    // said "solid" -- sessions 2/3 for this same exam need to actually
    // reflect that (lower priority) right now, not keep whatever they were
    // stamped with back when the exam was still unknown/shaky.
    restampSessionPriorities(examEvent.id);
    const suggestion=evaluateExamPrepAdjustment(updatedExam,nextEvents,getSchedulePreferences());
    if(suggestion){
      if(catchUpBanner)queueInsightNudge("examPrep",suggestion);
      else setExamPrepSuggestion(suggestion);
    }
  };
  // Shared by accept/dismiss below -- interval position (session N of M,
  // days-to-exam) is the field the interval-tolerance constraint on Tier 0
