    const deleteAllOccurrences=!!(opts&&opts.allOccurrences&&ev.googleRecurringId);
    const idsToRemove=deleteAllOccurrences
      ?new Set(events.filter(e=>e.googleRecurringId===ev.googleRecurringId).map(e=>e.id))
      :new Set([ev.id]);
